-- table action_permissions
CREATE TABLE action_permissions (
	policy_version_id TEXT NOT NULL, 
	action_type TEXT NOT NULL, 
	actor_role TEXT NOT NULL, 
	PRIMARY KEY (policy_version_id, action_type, actor_role), 
	FOREIGN KEY(policy_version_id) REFERENCES policy_versions (policy_version_id) ON DELETE CASCADE
);

-- table actions
CREATE TABLE actions (
	action_id TEXT NOT NULL, 
	action_type TEXT NOT NULL, 
	actor_id TEXT NOT NULL, 
	actor_role TEXT NOT NULL, 
	requested_at TEXT NOT NULL, 
	idempotency_key TEXT NOT NULL, 
	request_hash TEXT NOT NULL, 
	expected_versions_json TEXT DEFAULT '{}' NOT NULL, 
	payload_json TEXT NOT NULL, 
	policy_version TEXT NOT NULL, 
	status TEXT NOT NULL, 
	result_refs_json TEXT DEFAULT '[]' NOT NULL, 
	error_code TEXT, 
	error_detail TEXT, 
	committed_at TEXT, historical_replay INTEGER NOT NULL DEFAULT 0, replay_run_id TEXT NULL REFERENCES historical_replay_runs(replay_run_id) ON DELETE RESTRICT, 
	PRIMARY KEY (action_id), 
	UNIQUE (idempotency_key), 
	FOREIGN KEY(policy_version) REFERENCES policy_versions (policy_version_id) ON DELETE RESTRICT
);

-- table adjudications
CREATE TABLE adjudications (
	adjudication_id TEXT NOT NULL, 
	subject_type TEXT NOT NULL, 
	subject_id TEXT NOT NULL, 
	decision TEXT NOT NULL, 
	actor_id TEXT NOT NULL, 
	reason TEXT NOT NULL, 
	evidence_rejected_json TEXT NOT NULL, 
	alternative_json TEXT NOT NULL, 
	created_at TEXT NOT NULL, 
	supersedes_adjudication_id TEXT, 
	PRIMARY KEY (adjudication_id)
);

-- table agent_proposals
CREATE TABLE agent_proposals (
	agent_proposal_id TEXT NOT NULL, 
	subject_type TEXT NOT NULL, 
	subject_id TEXT NOT NULL, 
	proposal_type TEXT NOT NULL, 
	information_cutoff_at TEXT, 
	operator_prompt TEXT, 
	payload_json TEXT NOT NULL, 
	citation_refs_json TEXT NOT NULL, 
	model_name TEXT NOT NULL, 
	model_version TEXT NOT NULL, 
	status TEXT NOT NULL, 
	version INTEGER NOT NULL, 
	created_at TEXT NOT NULL, 
	resolved_at TEXT, 
	resolved_by_action_id TEXT, 
	PRIMARY KEY (agent_proposal_id)
);

-- table artifact_retrievals
CREATE TABLE artifact_retrievals (
	artifact_retrieval_id TEXT NOT NULL, 
	artifact_id TEXT NOT NULL, 
	source_run_id TEXT, 
	source_name TEXT NOT NULL, 
	source_type TEXT NOT NULL, 
	reported_content_type TEXT NOT NULL, 
	canonical_url TEXT, 
	requested_url TEXT, 
	published_at TEXT, 
	retrieved_at TEXT NOT NULL, 
	status TEXT NOT NULL, 
	PRIMARY KEY (artifact_retrieval_id), 
	FOREIGN KEY(artifact_id) REFERENCES source_artifacts (artifact_id) ON DELETE RESTRICT, 
	FOREIGN KEY(source_run_id) REFERENCES source_runs (source_run_id) ON DELETE RESTRICT
);

-- table audited_ticket_artifacts
CREATE TABLE audited_ticket_artifacts (
	ticket_artifact_id TEXT NOT NULL, 
	ticket_batch_revision_id TEXT NOT NULL, 
	ticket_index INTEGER NOT NULL, 
	ticket_hash TEXT NOT NULL, 
	source_artifact_id TEXT NOT NULL, 
	amount FLOAT NOT NULL, 
	currency TEXT NOT NULL, 
	channel TEXT NOT NULL, 
	deadline_at TEXT NOT NULL, 
	payload_json TEXT NOT NULL, 
	approved_at TEXT NOT NULL, 
	approved_by_action_id TEXT NOT NULL, 
	PRIMARY KEY (ticket_artifact_id), 
	CONSTRAINT ck_ticket_artifact_index CHECK (ticket_index >= 0), 
	CONSTRAINT ck_ticket_artifact_amount CHECK (amount > 0), 
	CONSTRAINT uq_ticket_artifact_revision_index UNIQUE (ticket_batch_revision_id, ticket_index), 
	FOREIGN KEY(ticket_batch_revision_id) REFERENCES ticket_batch_revisions (ticket_batch_revision_id) ON DELETE RESTRICT, 
	UNIQUE (ticket_hash), 
	FOREIGN KEY(source_artifact_id) REFERENCES source_artifacts (artifact_id) ON DELETE RESTRICT, 
	FOREIGN KEY(approved_by_action_id) REFERENCES actions (action_id) ON DELETE RESTRICT
);

-- table bet_leg_settlements
CREATE TABLE bet_leg_settlements (
	bet_leg_settlement_id TEXT NOT NULL, 
	bet_leg_id TEXT NOT NULL, 
	outcome_id TEXT NOT NULL, 
	grade TEXT NOT NULL, 
	hit INTEGER, 
	settlement_method_version TEXT NOT NULL, 
	PRIMARY KEY (bet_leg_settlement_id), 
	FOREIGN KEY(bet_leg_id) REFERENCES bet_legs (bet_leg_id) ON DELETE RESTRICT, 
	FOREIGN KEY(outcome_id) REFERENCES match_outcomes (outcome_id) ON DELETE RESTRICT
);

-- table bet_legs
CREATE TABLE bet_legs (
	bet_leg_id TEXT NOT NULL, 
	ticket_id TEXT NOT NULL, 
	forecast_revision_id TEXT NOT NULL, 
	match_id TEXT NOT NULL, 
	market_definition_id TEXT NOT NULL, 
	selection_id TEXT NOT NULL, 
	entry_quote_id TEXT, 
	line TEXT, 
	stake_share FLOAT, 
	entry_odds FLOAT, 
	PRIMARY KEY (bet_leg_id), 
	FOREIGN KEY(ticket_id) REFERENCES tickets (ticket_id) ON DELETE RESTRICT, 
	FOREIGN KEY(forecast_revision_id) REFERENCES forecast_revisions (forecast_revision_id) ON DELETE RESTRICT, 
	FOREIGN KEY(match_id) REFERENCES matches (match_id) ON DELETE RESTRICT, 
	FOREIGN KEY(market_definition_id) REFERENCES market_definitions (market_definition_id) ON DELETE RESTRICT, 
	FOREIGN KEY(selection_id) REFERENCES selection_definitions (selection_id) ON DELETE RESTRICT, 
	FOREIGN KEY(entry_quote_id) REFERENCES market_quotes (quote_id) ON DELETE RESTRICT
);

-- table budget_policies
CREATE TABLE budget_policies (
	budget_policy_id TEXT NOT NULL, 
	policy_version TEXT NOT NULL, 
	channel TEXT NOT NULL, 
	total_cap FLOAT NOT NULL, 
	bucket_caps_json TEXT NOT NULL, 
	status TEXT NOT NULL, 
	effective_at TEXT NOT NULL, 
	created_at TEXT NOT NULL, 
	PRIMARY KEY (budget_policy_id)
);

-- table cash_accounts
CREATE TABLE cash_accounts (
	account_id TEXT NOT NULL, 
	channel_scope TEXT NOT NULL, 
	currency TEXT NOT NULL, 
	status TEXT NOT NULL, 
	PRIMARY KEY (account_id)
);

-- table cash_transactions
CREATE TABLE cash_transactions (
	transaction_id TEXT NOT NULL, 
	account_id TEXT NOT NULL, 
	ticket_id TEXT, 
	ticket_settlement_id TEXT, 
	kind TEXT NOT NULL, 
	amount FLOAT NOT NULL, 
	amount_minor INTEGER, 
	currency TEXT, 
	occurred_at TEXT NOT NULL, 
	idempotency_key TEXT NOT NULL, 
	PRIMARY KEY (transaction_id), 
	CONSTRAINT ck_cash_transactions_v2_money CHECK ((amount_minor IS NULL AND currency IS NULL) OR (amount_minor IS NOT NULL AND amount_minor != 0 AND currency IS NOT NULL AND length(currency) = 3)), 
	FOREIGN KEY(account_id) REFERENCES cash_accounts (account_id) ON DELETE RESTRICT, 
	FOREIGN KEY(ticket_id) REFERENCES tickets (ticket_id) ON DELETE RESTRICT, 
	UNIQUE (idempotency_key)
);

-- table claim_evidence_spans
CREATE TABLE claim_evidence_spans (
	claim_evidence_span_id TEXT NOT NULL, 
	claim_id TEXT NOT NULL, 
	artifact_id TEXT NOT NULL, 
	artifact_retrieval_id TEXT NOT NULL, 
	quote TEXT NOT NULL, 
	locator TEXT, 
	PRIMARY KEY (claim_evidence_span_id), 
	FOREIGN KEY(claim_id) REFERENCES claims (claim_id) ON DELETE RESTRICT, 
	FOREIGN KEY(artifact_id) REFERENCES source_artifacts (artifact_id) ON DELETE RESTRICT, 
	FOREIGN KEY(artifact_retrieval_id) REFERENCES artifact_retrievals (artifact_retrieval_id) ON DELETE RESTRICT
);

-- table claim_status_events
CREATE TABLE claim_status_events (
	claim_status_event_id TEXT NOT NULL, 
	claim_id TEXT NOT NULL, 
	from_status TEXT, 
	to_status TEXT NOT NULL, 
	action_id TEXT NOT NULL, 
	at TEXT NOT NULL, 
	PRIMARY KEY (claim_status_event_id), 
	FOREIGN KEY(claim_id) REFERENCES claims (claim_id) ON DELETE RESTRICT
);

-- table claims
CREATE TABLE claims (
	claim_id TEXT NOT NULL, 
	subject_type TEXT NOT NULL, 
	subject_id TEXT NOT NULL, 
	predicate TEXT NOT NULL, 
	value_json TEXT NOT NULL, 
	scope_match_id TEXT, 
	valid_from TEXT NOT NULL, 
	valid_to TEXT, 
	status TEXT NOT NULL, 
	extractor TEXT NOT NULL, 
	extractor_version TEXT NOT NULL, 
	created_at TEXT NOT NULL, 
	adjudicated_at TEXT, 
	PRIMARY KEY (claim_id), 
	FOREIGN KEY(scope_match_id) REFERENCES matches (match_id) ON DELETE RESTRICT
);

-- table competition_editions
CREATE TABLE competition_editions (
	competition_edition_id TEXT NOT NULL, 
	competition_id TEXT NOT NULL, 
	name TEXT NOT NULL, 
	country TEXT, 
	format TEXT, 
	season_label TEXT, 
	stage TEXT, 
	valid_from TEXT, 
	valid_to TEXT, 
	PRIMARY KEY (competition_edition_id), 
	FOREIGN KEY(competition_id) REFERENCES competitions (competition_id) ON DELETE RESTRICT
);

-- table competitions
CREATE TABLE competitions (
	competition_id TEXT NOT NULL, 
	name TEXT NOT NULL, 
	country TEXT, 
	kind TEXT NOT NULL, 
	PRIMARY KEY (competition_id)
);

-- table decision_sessions
CREATE TABLE decision_sessions (
	decision_session_id TEXT NOT NULL, 
	opened_at TEXT NOT NULL, 
	operator_id TEXT NOT NULL, 
	cutoff_at TEXT NOT NULL, 
	scope_json TEXT NOT NULL, 
	status TEXT NOT NULL, 
	closed_at TEXT, 
	PRIMARY KEY (decision_session_id)
);

-- table discovery_node_evaluations
CREATE TABLE discovery_node_evaluations (
	node_evaluation_id TEXT NOT NULL, 
	node_id TEXT NOT NULL, 
	revision_no INTEGER NOT NULL, 
	supersedes_evaluation_id TEXT, 
	evaluator_revision TEXT NOT NULL, 
	result_json TEXT NOT NULL, 
	selectable INTEGER NOT NULL, 
	evaluated_at TEXT NOT NULL, 
	action_id TEXT NOT NULL, 
	PRIMARY KEY (node_evaluation_id), 
	UNIQUE (node_id, revision_no), 
	FOREIGN KEY(node_id) REFERENCES discovery_nodes (node_id) ON DELETE RESTRICT, 
	FOREIGN KEY(supersedes_evaluation_id) REFERENCES discovery_node_evaluations (node_evaluation_id) ON DELETE RESTRICT
);

-- table discovery_nodes
CREATE TABLE discovery_nodes (
	node_id TEXT NOT NULL, 
	world_id TEXT NOT NULL, 
	discovery_run_id TEXT, 
	parent_node_id TEXT, 
	depth INTEGER NOT NULL, 
	sibling_order INTEGER NOT NULL, 
	creation_sequence INTEGER NOT NULL, 
	continuation_action_json TEXT, 
	policy_decision_json TEXT, 
	artifact_manifest_hash TEXT, 
	artifact_manifest_json TEXT, 
	business_refs_json TEXT, 
	execution_status TEXT NOT NULL, 
	diagnostic_codes_json TEXT NOT NULL, 
	started_at TEXT NOT NULL, 
	finished_at TEXT, 
	latency_ms INTEGER, 
	resource_cost_json TEXT, 
	retry_of_node_id TEXT, 
	terminal_reason TEXT, 
	frontier_eligible INTEGER NOT NULL, 
	visibility_sequence INTEGER, 
	action_id TEXT NOT NULL, 
	PRIMARY KEY (node_id), 
	UNIQUE (world_id, creation_sequence), 
	UNIQUE (world_id, visibility_sequence), 
	FOREIGN KEY(world_id) REFERENCES discovery_worlds (world_id) ON DELETE RESTRICT, 
	FOREIGN KEY(discovery_run_id) REFERENCES discovery_runs (discovery_run_id) ON DELETE RESTRICT, 
	FOREIGN KEY(parent_node_id) REFERENCES discovery_nodes (node_id) ON DELETE RESTRICT, 
	FOREIGN KEY(retry_of_node_id) REFERENCES discovery_nodes (node_id) ON DELETE RESTRICT
);

-- table discovery_runs
CREATE TABLE discovery_runs (
	discovery_run_id TEXT NOT NULL, 
	world_id TEXT NOT NULL, 
	policy_revision_id TEXT NOT NULL, 
	environment_mode TEXT NOT NULL, 
	started_at TEXT NOT NULL, 
	action_id TEXT NOT NULL, 
	PRIMARY KEY (discovery_run_id), 
	FOREIGN KEY(world_id) REFERENCES discovery_worlds (world_id) ON DELETE RESTRICT, 
	FOREIGN KEY(policy_revision_id) REFERENCES exploration_policy_revisions (policy_revision_id) ON DELETE RESTRICT
);

-- table discovery_world_events
CREATE TABLE discovery_world_events (
	world_event_id TEXT NOT NULL, 
	world_id TEXT NOT NULL, 
	sequence_no INTEGER NOT NULL, 
	event_kind TEXT NOT NULL, 
	reason TEXT, 
	manifest_hash TEXT, 
	occurred_at TEXT NOT NULL, 
	action_id TEXT NOT NULL, 
	PRIMARY KEY (world_event_id), 
	UNIQUE (world_id, sequence_no), 
	FOREIGN KEY(world_id) REFERENCES discovery_worlds (world_id) ON DELETE RESTRICT
);

-- table discovery_worlds
CREATE TABLE discovery_worlds (
	world_id TEXT NOT NULL, 
	task_family TEXT NOT NULL, 
	business_date TEXT NOT NULL, 
	lane TEXT NOT NULL, 
	strata_json TEXT NOT NULL, 
	input_manifest_hash TEXT NOT NULL, 
	input_manifest_json TEXT NOT NULL, 
	pilot_contract_hash TEXT NOT NULL, 
	legal_action_schema_json TEXT NOT NULL, 
	evaluator_revision TEXT NOT NULL, 
	resource_budget_json TEXT NOT NULL, 
	cutoff_at TEXT NOT NULL, 
	provenance_mode TEXT NOT NULL, 
	isolated_store_identity TEXT NOT NULL, 
	root_node_id TEXT, 
	created_at TEXT NOT NULL, 
	action_id TEXT NOT NULL, 
	PRIMARY KEY (world_id)
);

-- table entity_aliases
CREATE TABLE entity_aliases (
	entity_id TEXT NOT NULL, 
	entity_type TEXT NOT NULL, 
	normalized_alias TEXT NOT NULL, 
