	actor_id TEXT NOT NULL, 
	at TEXT NOT NULL, 
	reversible INTEGER DEFAULT 1 NOT NULL, 
	PRIMARY KEY (merge_id)
);

-- table evidence_bundle_items
CREATE TABLE evidence_bundle_items (
	item_id TEXT NOT NULL, 
	evidence_bundle_id TEXT NOT NULL, 
	item_type TEXT NOT NULL, 
	observation_id TEXT, 
	claim_id TEXT, 
	PRIMARY KEY (item_id), 
	FOREIGN KEY(evidence_bundle_id) REFERENCES evidence_bundles (evidence_bundle_id) ON DELETE RESTRICT
);

-- table evidence_bundles
CREATE TABLE evidence_bundles (
	evidence_bundle_id TEXT NOT NULL, 
	match_id TEXT NOT NULL, 
	decision_session_id TEXT, 
	frozen_at TEXT NOT NULL, 
	information_cutoff_at TEXT NOT NULL, 
	market_snapshot_id TEXT, 
	prior_distribution_json TEXT NOT NULL, 
	identity_resolution_version TEXT, 
	source_coverage_json TEXT NOT NULL, 
	freshness_json TEXT NOT NULL, 
	content_hash TEXT NOT NULL, 
	PRIMARY KEY (evidence_bundle_id), 
	FOREIGN KEY(match_id) REFERENCES matches (match_id) ON DELETE RESTRICT, 
	FOREIGN KEY(market_snapshot_id) REFERENCES market_snapshots (market_snapshot_id) ON DELETE RESTRICT
);

-- table exploration_policy_parent_links
CREATE TABLE exploration_policy_parent_links (
	policy_revision_id TEXT NOT NULL, 
	parent_index INTEGER NOT NULL, 
	parent_policy_revision_id TEXT NOT NULL, 
	PRIMARY KEY (policy_revision_id, parent_index), 
	FOREIGN KEY(policy_revision_id) REFERENCES exploration_policy_revisions (policy_revision_id) ON DELETE RESTRICT, 
	FOREIGN KEY(parent_policy_revision_id) REFERENCES exploration_policy_revisions (policy_revision_id) ON DELETE RESTRICT
);

-- table exploration_policy_revisions
CREATE TABLE exploration_policy_revisions (
	policy_revision_id TEXT NOT NULL, 
	family TEXT NOT NULL, 
	source_artifact_hash TEXT NOT NULL, 
	interface_version TEXT NOT NULL, 
	constraints_version TEXT NOT NULL, 
	generator_family TEXT NOT NULL, 
	generator_revision TEXT NOT NULL, 
	generation_trace_hash TEXT, 
	generator_descriptors_json TEXT NOT NULL, 
	generation_input_manifest_hash TEXT NOT NULL, 
	generation_budget_json TEXT NOT NULL, 
	generation_cost_json TEXT NOT NULL, 
	generation_timeout_seconds INTEGER NOT NULL, 
	rationale TEXT NOT NULL, 
	change_summary TEXT NOT NULL, 
	configuration_json TEXT NOT NULL, 
	random_seed_policy_json TEXT NOT NULL, 
	compatible_world_families_json TEXT NOT NULL, 
	max_resource_permissions_json TEXT NOT NULL, 
	change_surfaces_json TEXT NOT NULL, 
	novelty_descriptors_json TEXT NOT NULL, 
	validation_result_json TEXT NOT NULL, 
	created_by TEXT NOT NULL, 
	created_at TEXT NOT NULL, 
	action_id TEXT NOT NULL, 
	PRIMARY KEY (policy_revision_id)
);

-- table external_identifiers
CREATE TABLE external_identifiers (
	entity_id TEXT NOT NULL, 
	entity_type TEXT NOT NULL, 
	provider TEXT NOT NULL, 
	external_id TEXT NOT NULL, 
	valid_from TEXT, 
	valid_to TEXT, 
	CONSTRAINT pk_external_identifiers PRIMARY KEY (provider, entity_type, external_id)
);

-- table factor_applications
CREATE TABLE factor_applications (
	factor_application_id TEXT NOT NULL, 
	forecast_revision_id TEXT NOT NULL, 
	factor_definition_id TEXT NOT NULL, 
	scope_entity_ids_json TEXT NOT NULL, 
	delta_distribution_json TEXT NOT NULL, 
	supporting_observation_ids_json TEXT NOT NULL, 
	note TEXT, 
	PRIMARY KEY (factor_application_id), 
	FOREIGN KEY(forecast_revision_id) REFERENCES forecast_revisions (forecast_revision_id) ON DELETE RESTRICT
);

-- table factor_definitions
CREATE TABLE factor_definitions (
	factor_definition_id TEXT NOT NULL, 
	factor_family_id TEXT NOT NULL, 
	version INTEGER NOT NULL, 
	name TEXT NOT NULL, 
	definition TEXT, 
	scope TEXT, 
	status TEXT NOT NULL, 
	born_from_refs_json TEXT NOT NULL, 
	valid_from TEXT NOT NULL, 
	valid_to TEXT, 
	policy_version TEXT NOT NULL, 
	PRIMARY KEY (factor_definition_id), 
	CONSTRAINT uq_factor_definitions_family_version UNIQUE (factor_family_id, version), 
	FOREIGN KEY(factor_family_id) REFERENCES factor_families (factor_family_id) ON DELETE RESTRICT
);

-- table factor_families
CREATE TABLE factor_families (
	factor_family_id TEXT NOT NULL, 
	name TEXT NOT NULL, 
	definition TEXT, 
	PRIMARY KEY (factor_family_id)
);

-- table flag_instances
CREATE TABLE flag_instances (
	flag_instance_id TEXT NOT NULL, 
	flag_type TEXT NOT NULL, 
	match_id TEXT NOT NULL, 
	direction TEXT, 
	strength FLOAT NOT NULL, 
	evidence_refs_json TEXT NOT NULL, 
	predicted_face TEXT, 
	status TEXT NOT NULL, 
	created_at TEXT NOT NULL, 
	PRIMARY KEY (flag_instance_id), 
	FOREIGN KEY(match_id) REFERENCES matches (match_id) ON DELETE RESTRICT
);

-- table forecast_revisions
CREATE TABLE forecast_revisions (
	forecast_revision_id TEXT NOT NULL, 
	forecast_series_id TEXT NOT NULL, 
	decision_session_id TEXT, 
	revision_no INTEGER NOT NULL, 
	status TEXT NOT NULL, 
	made_at TEXT NOT NULL, 
	information_cutoff_at TEXT, 
	prior_snapshot_id TEXT, 
	prior_distribution_json TEXT NOT NULL, 
	belief_distribution_json TEXT NOT NULL, 
	evidence_bundle_id TEXT, 
	falsifier TEXT, 
	actor_id TEXT NOT NULL, 
	model_name TEXT, 
	model_version TEXT, 
	policy_version TEXT NOT NULL, 
	commitment_tier TEXT NOT NULL, 
	evidence_coverage FLOAT, 
	evidence_quality FLOAT, 
	forecast_stability FLOAT, 
	supersedes_revision_id TEXT, 
	kind TEXT, 
	board_key TEXT, 
	judgment_json TEXT, 
	PRIMARY KEY (forecast_revision_id), 
	CONSTRAINT uq_forecast_revisions_series_no UNIQUE (forecast_series_id, revision_no), 
	FOREIGN KEY(forecast_series_id) REFERENCES forecast_series (forecast_series_id) ON DELETE RESTRICT, 
	FOREIGN KEY(prior_snapshot_id) REFERENCES market_snapshots (market_snapshot_id) ON DELETE RESTRICT, 
	FOREIGN KEY(evidence_bundle_id) REFERENCES evidence_bundles (evidence_bundle_id) ON DELETE RESTRICT
);

-- table forecast_series
CREATE TABLE forecast_series (
	forecast_series_id TEXT NOT NULL, 
	match_id TEXT NOT NULL, 
	market_definition_id TEXT NOT NULL, 
	PRIMARY KEY (forecast_series_id), 
	CONSTRAINT uq_forecast_series_match_market UNIQUE (match_id, market_definition_id), 
	FOREIGN KEY(match_id) REFERENCES matches (match_id) ON DELETE RESTRICT, 
	FOREIGN KEY(market_definition_id) REFERENCES market_definitions (market_definition_id) ON DELETE RESTRICT
);

-- table historical_replay_runs
CREATE TABLE historical_replay_runs (
	replay_run_id TEXT NOT NULL, 
	business_date TEXT NOT NULL, 
	source_root_fingerprint TEXT NOT NULL, 
	source_manifest_hash TEXT NOT NULL, 
	isolated_database_identity TEXT NOT NULL, 
	schema_version INTEGER NOT NULL, 
	status TEXT NOT NULL, 
	started_at TEXT NOT NULL, 
	finished_at TEXT, 
	production_before_json TEXT NOT NULL, 
	production_after_json TEXT, 
	report_sha256 TEXT, 
	failure_codes_json TEXT DEFAULT '[]' NOT NULL, 
	PRIMARY KEY (replay_run_id), 
	CONSTRAINT ck_historical_replay_runs_status CHECK (status IN ('running', 'accepted', 'failed')), 
	CONSTRAINT ck_historical_replay_schema_version CHECK (schema_version >= 1), 
	CONSTRAINT uq_historical_replay_identity UNIQUE (business_date, source_manifest_hash, isolated_database_identity)
);

-- table lineup_entries
CREATE TABLE lineup_entries (
	lineup_entry_id TEXT NOT NULL, 
	match_id TEXT NOT NULL, 
	person_id TEXT NOT NULL, 
	team_appearance_id TEXT, 
	lineup_status TEXT NOT NULL, 
	role TEXT NOT NULL, 
	position TEXT, 
	shirt_number TEXT, 
	captain INTEGER DEFAULT 0 NOT NULL, 
	observed_at TEXT NOT NULL, 
	observation_id TEXT, 
	PRIMARY KEY (lineup_entry_id), 
	FOREIGN KEY(match_id) REFERENCES matches (match_id) ON DELETE RESTRICT, 
	FOREIGN KEY(person_id) REFERENCES persons (person_id) ON DELETE RESTRICT, 
	FOREIGN KEY(team_appearance_id) REFERENCES team_appearances (team_appearance_id) ON DELETE RESTRICT
);

-- table market_definitions
CREATE TABLE market_definitions (
	market_definition_id TEXT NOT NULL, 
	market_kind TEXT NOT NULL, 
	settlement_scope TEXT NOT NULL, 
	ordered INTEGER DEFAULT 0 NOT NULL, 
	line_schema TEXT, 
	outcome_schema_version TEXT NOT NULL, 
	PRIMARY KEY (market_definition_id)
);

-- table market_quotes
CREATE TABLE market_quotes (
	quote_id TEXT NOT NULL, 
	match_id TEXT NOT NULL, 
	market_definition_id TEXT NOT NULL, 
	selection_id TEXT NOT NULL, 
	provider TEXT NOT NULL, 
	bookmaker TEXT, 
	decimal_odds FLOAT NOT NULL, 
	settlement_parameter_decimal TEXT, 
	captured_at TEXT NOT NULL, 
	artifact_retrieval_id TEXT, 
	quote_status TEXT NOT NULL, 
	PRIMARY KEY (quote_id), 
	CONSTRAINT ck_market_quotes_odds CHECK (decimal_odds > 1.0), 
	FOREIGN KEY(match_id) REFERENCES matches (match_id) ON DELETE RESTRICT, 
	FOREIGN KEY(market_definition_id) REFERENCES market_definitions (market_definition_id) ON DELETE RESTRICT, 
	FOREIGN KEY(selection_id) REFERENCES selection_definitions (selection_id) ON DELETE RESTRICT, 
	FOREIGN KEY(artifact_retrieval_id) REFERENCES artifact_retrievals (artifact_retrieval_id) ON DELETE RESTRICT
);

-- table market_snapshot_quotes
CREATE TABLE market_snapshot_quotes (
	market_snapshot_id TEXT NOT NULL, 
	quote_id TEXT NOT NULL, 
	CONSTRAINT pk_market_snapshot_quotes PRIMARY KEY (market_snapshot_id, quote_id), 
	FOREIGN KEY(market_snapshot_id) REFERENCES market_snapshots (market_snapshot_id) ON DELETE RESTRICT, 
	FOREIGN KEY(quote_id) REFERENCES market_quotes (quote_id) ON DELETE RESTRICT
);

-- table market_snapshots
CREATE TABLE market_snapshots (
	market_snapshot_id TEXT NOT NULL, 
	match_id TEXT NOT NULL, 
	market_definition_id TEXT NOT NULL, 
	snapshot_kind TEXT NOT NULL, 
	as_of TEXT NOT NULL, 
	fair_distribution_json TEXT NOT NULL, 
	devig_method TEXT NOT NULL, 
	method_version TEXT NOT NULL, 
	source_coverage_json TEXT NOT NULL, 
	freshness_json TEXT NOT NULL, 
	disagreement_json TEXT NOT NULL, 
	PRIMARY KEY (market_snapshot_id), 
	FOREIGN KEY(match_id) REFERENCES matches (match_id) ON DELETE RESTRICT, 
	FOREIGN KEY(market_definition_id) REFERENCES market_definitions (market_definition_id) ON DELETE RESTRICT
);

-- table match_outcomes
CREATE TABLE match_outcomes (
	outcome_id TEXT NOT NULL, 
	match_id TEXT NOT NULL, 
	version INTEGER NOT NULL, 
	score_90 TEXT NOT NULL, 
	score_aet TEXT, 
	penalties TEXT, 
	status TEXT NOT NULL, 
	source_artifact_retrieval_ids_json TEXT NOT NULL, 
	recorded_at TEXT NOT NULL, 
	supersedes_outcome_id TEXT, 
	PRIMARY KEY (outcome_id), 
	CONSTRAINT uq_match_outcomes_match_version UNIQUE (match_id, version), 
	FOREIGN KEY(match_id) REFERENCES matches (match_id) ON DELETE RESTRICT
);

-- table match_revisions
CREATE TABLE match_revisions (
	match_revision_id TEXT NOT NULL, 
	match_id TEXT NOT NULL, 
	version INTEGER NOT NULL, 
	competition_edition_id TEXT, 
	scheduled_at TEXT, 
	schedule_status TEXT NOT NULL, 
	venue_id TEXT, 
	status TEXT NOT NULL, 
	round_label TEXT, 
	recorded_at TEXT NOT NULL, 
	supersedes_revision_id TEXT, 
	PRIMARY KEY (match_revision_id), 
	CONSTRAINT uq_match_revisions_match_version UNIQUE (match_id, version), 
	FOREIGN KEY(match_id) REFERENCES matches (match_id) ON DELETE RESTRICT, 
	FOREIGN KEY(competition_edition_id) REFERENCES competition_editions (competition_edition_id) ON DELETE RESTRICT, 
	FOREIGN KEY(venue_id) REFERENCES venues (venue_id) ON DELETE RESTRICT
);

-- table matches
CREATE TABLE matches (
	match_id TEXT NOT NULL, 
	current_revision_id TEXT, 
	PRIMARY KEY (match_id)
);

-- table observation_claims
CREATE TABLE observation_claims (
	observation_id TEXT NOT NULL, 
	claim_id TEXT NOT NULL, 
	CONSTRAINT pk_observation_claims PRIMARY KEY (observation_id, claim_id), 
	FOREIGN KEY(observation_id) REFERENCES observations (observation_id) ON DELETE RESTRICT, 
	FOREIGN KEY(claim_id) REFERENCES claims (claim_id) ON DELETE RESTRICT
);

-- table observation_sources
CREATE TABLE observation_sources (
	observation_id TEXT NOT NULL, 
	artifact_retrieval_id TEXT NOT NULL, 
	CONSTRAINT pk_observation_sources PRIMARY KEY (observation_id, artifact_retrieval_id), 
	FOREIGN KEY(observation_id) REFERENCES observations (observation_id) ON DELETE RESTRICT, 
	FOREIGN KEY(artifact_retrieval_id) REFERENCES artifact_retrievals (artifact_retrieval_id) ON DELETE RESTRICT
);

-- table observations
CREATE TABLE observations (
	observation_id TEXT NOT NULL, 
	observation_type TEXT NOT NULL, 
	subject_type TEXT NOT NULL, 
	subject_id TEXT NOT NULL, 
	scope_match_id TEXT, 
	value_json TEXT NOT NULL, 
	schema_version TEXT NOT NULL, 
	valid_from TEXT NOT NULL, 
	valid_to TEXT, 
	observed_at TEXT NOT NULL, 
	recorded_at TEXT NOT NULL, 
	verification_method TEXT NOT NULL, 
	quality_json TEXT NOT NULL, 
	PRIMARY KEY (observation_id), 
	FOREIGN KEY(scope_match_id) REFERENCES matches (match_id) ON DELETE RESTRICT
);

-- table official_offer_families
CREATE TABLE official_offer_families (
	official_offer_family_id TEXT NOT NULL, 
	lane TEXT NOT NULL, 
	business_key TEXT NOT NULL, 
	official_match_no TEXT NOT NULL, 
	match_id TEXT NOT NULL, 
	created_at TEXT NOT NULL, 
	PRIMARY KEY (official_offer_family_id), 
	CONSTRAINT ck_official_offer_families_lane CHECK (lane IN ('jczq', 'zucai')), 
	CONSTRAINT uq_official_offer_family_identity UNIQUE (lane, business_key, official_match_no, match_id), 
	FOREIGN KEY(match_id) REFERENCES matches (match_id) ON DELETE RESTRICT
);

-- table official_offer_revisions
CREATE TABLE official_offer_revisions (
	official_offer_revision_id TEXT NOT NULL, 
	official_offer_family_id TEXT NOT NULL, 
	slate_revision_id TEXT NOT NULL, 
	match_id TEXT NOT NULL, 
	official_match_no TEXT NOT NULL, 
	market_definition_ids_json TEXT NOT NULL, 
	sale_opens_at TEXT NOT NULL, 
	sale_deadline_at TEXT NOT NULL, 
	status TEXT NOT NULL, 
	PRIMARY KEY (official_offer_revision_id), 
	CONSTRAINT ck_official_offer_status CHECK (status IN ('scheduled', 'on_sale', 'sale_closed', 'cancelled')), 
	CONSTRAINT uq_official_offer_per_slate UNIQUE (slate_revision_id, official_offer_family_id), 
	CONSTRAINT uq_official_offer_number_per_slate UNIQUE (slate_revision_id, official_match_no), 
	FOREIGN KEY(official_offer_family_id) REFERENCES official_offer_families (official_offer_family_id) ON DELETE RESTRICT, 
	FOREIGN KEY(slate_revision_id) REFERENCES official_sale_slate_revisions (slate_revision_id) ON DELETE RESTRICT, 
	FOREIGN KEY(match_id) REFERENCES matches (match_id) ON DELETE RESTRICT
);

-- table official_sale_slate_revisions
CREATE TABLE official_sale_slate_revisions (
	slate_revision_id TEXT NOT NULL, 
	slate_family_id TEXT NOT NULL, 
	lane TEXT NOT NULL, 
	business_key TEXT NOT NULL, 
	revision_no INTEGER NOT NULL, 
	source_artifact_retrieval_id TEXT NOT NULL, 
	published_at TEXT NOT NULL, 
	retrieved_at TEXT NOT NULL, 
	valid_from TEXT NOT NULL, 
	supersedes_slate_revision_id TEXT, 
	content_hash TEXT NOT NULL, 
	PRIMARY KEY (slate_revision_id), 
	CONSTRAINT ck_official_slates_lane CHECK (lane IN ('jczq', 'zucai')), 
	CONSTRAINT ck_official_slates_revision CHECK (revision_no >= 1), 
	CONSTRAINT uq_official_slates_revision UNIQUE (lane, business_key, revision_no), 
	CONSTRAINT uq_official_slates_content UNIQUE (slate_family_id, content_hash), 
	FOREIGN KEY(source_artifact_retrieval_id) REFERENCES artifact_retrievals (artifact_retrieval_id) ON DELETE RESTRICT, 
	UNIQUE (supersedes_slate_revision_id), 
	FOREIGN KEY(supersedes_slate_revision_id) REFERENCES official_sale_slate_revisions (slate_revision_id) ON DELETE RESTRICT
);

-- table official_schedule_check_receipts
CREATE TABLE official_schedule_check_receipts (
	schedule_check_id TEXT NOT NULL, 
	action_id TEXT NOT NULL, 
	lane TEXT NOT NULL, 
	shanghai_check_date TEXT NOT NULL, 
	checked_at TEXT NOT NULL, 
	source_run_id TEXT NOT NULL, 
	check_state TEXT NOT NULL, 
	parser_contract_version TEXT, 
	official_source_content_hash TEXT, 
	official_source_artifact_retrieval_id TEXT, 
	observed_business_keys_json TEXT NOT NULL, 
	imported_business_keys_json TEXT NOT NULL, 
	error_code TEXT, 
	PRIMARY KEY (schedule_check_id), 
	CONSTRAINT ck_official_schedule_checks_lane CHECK (lane IN ('jczq', 'zucai')), 
	CONSTRAINT ck_official_schedule_check_state CHECK (check_state IN ('slate_imported', 'confirmed_no_sale', 'failed')), 
	CONSTRAINT uq_official_schedule_check_run_scope UNIQUE (source_run_id, lane, shanghai_check_date), 
	UNIQUE (action_id), 
	FOREIGN KEY(action_id) REFERENCES actions (action_id) ON DELETE RESTRICT, 
	FOREIGN KEY(source_run_id) REFERENCES source_runs (source_run_id) ON DELETE RESTRICT, 
	FOREIGN KEY(official_source_artifact_retrieval_id) REFERENCES artifact_retrievals (artifact_retrieval_id) ON DELETE RESTRICT
);

-- table operator_artifact_terminal_receipts
CREATE TABLE operator_artifact_terminal_receipts (
	artifact_terminal_receipt_id TEXT NOT NULL, 
	ticket_artifact_id TEXT NOT NULL, 
	challenge_revision_id TEXT, 
	terminal_kind TEXT NOT NULL, 
	terminal_reason TEXT NOT NULL, 
	effective_cutoff_at TEXT NOT NULL, 
	terminal_at TEXT NOT NULL, 
	action_id TEXT NOT NULL, 
	PRIMARY KEY (artifact_terminal_receipt_id), 
	CONSTRAINT ck_operator_artifact_terminal_kind CHECK (terminal_kind IN ('placed', 'shadow')), 
	CONSTRAINT ck_operator_artifact_terminal_reason CHECK ((terminal_kind = 'placed' AND terminal_reason = 'actual_placement_confirmed') OR (terminal_kind = 'shadow' AND terminal_reason IN ('confirmation_not_requested', 'deadline_unconfirmed', 'human_no_ticket', 'official_deadline_shortened', 'official_offer_cancelled'))), 
	UNIQUE (ticket_artifact_id), 
	FOREIGN KEY(ticket_artifact_id) REFERENCES audited_ticket_artifacts (ticket_artifact_id) ON DELETE RESTRICT, 
	UNIQUE (challenge_revision_id), 
	FOREIGN KEY(challenge_revision_id) REFERENCES operator_confirmation_challenge_revisions (challenge_revision_id) ON DELETE RESTRICT, 
	FOREIGN KEY(action_id) REFERENCES actions (action_id) ON DELETE RESTRICT
);

-- table operator_artifact_work_item_links
CREATE TABLE operator_artifact_work_item_links (
	artifact_work_item_link_id TEXT NOT NULL, 
	ticket_artifact_id TEXT NOT NULL, 
	task_family_id TEXT NOT NULL, 
	work_item_id TEXT NOT NULL, 
	task_snapshot_hash TEXT NOT NULL, 
	slate_revision_id TEXT NOT NULL, 
	action_id TEXT NOT NULL, 
	linked_at TEXT NOT NULL, 
	PRIMARY KEY (artifact_work_item_link_id), 
	UNIQUE (ticket_artifact_id), 
	FOREIGN KEY(ticket_artifact_id) REFERENCES audited_ticket_artifacts (ticket_artifact_id) ON DELETE RESTRICT, 
	FOREIGN KEY(slate_revision_id) REFERENCES official_sale_slate_revisions (slate_revision_id) ON DELETE RESTRICT, 
	FOREIGN KEY(action_id) REFERENCES actions (action_id) ON DELETE RESTRICT
);

-- table operator_baseline_envelope_bundle_faces
CREATE TABLE operator_baseline_envelope_bundle_faces (
	baseline_envelope_bundle_face_id TEXT NOT NULL, 
	baseline_envelope_face_bundle_id TEXT NOT NULL, 
	face_index INTEGER NOT NULL, 
	face_code TEXT NOT NULL, 
	PRIMARY KEY (baseline_envelope_bundle_face_id), 
	CONSTRAINT ck_baseline_bundle_face_index CHECK (face_index >= 0), 
	CONSTRAINT uq_baseline_bundle_face_index UNIQUE (baseline_envelope_face_bundle_id, face_index), 
	CONSTRAINT uq_baseline_bundle_face_code UNIQUE (baseline_envelope_face_bundle_id, face_code), 
	FOREIGN KEY(baseline_envelope_face_bundle_id) REFERENCES operator_baseline_envelope_face_bundles (baseline_envelope_face_bundle_id) ON DELETE RESTRICT
);

-- table operator_baseline_envelope_face_bundles
CREATE TABLE operator_baseline_envelope_face_bundles (
	baseline_envelope_face_bundle_id TEXT NOT NULL, 
	baseline_envelope_offer_constraint_id TEXT NOT NULL, 
	bundle_index INTEGER NOT NULL, 
	bundle_code TEXT NOT NULL, 
	PRIMARY KEY (baseline_envelope_face_bundle_id), 
	CONSTRAINT ck_baseline_face_bundle_index CHECK (bundle_index >= 0), 
	CONSTRAINT uq_baseline_face_bundle_index UNIQUE (baseline_envelope_offer_constraint_id, bundle_index), 
	CONSTRAINT uq_baseline_face_bundle_code UNIQUE (baseline_envelope_offer_constraint_id, bundle_code), 
	FOREIGN KEY(baseline_envelope_offer_constraint_id) REFERENCES operator_baseline_envelope_offer_constraints (baseline_envelope_offer_constraint_id) ON DELETE RESTRICT
);

-- table operator_baseline_envelope_offer_constraints
CREATE TABLE operator_baseline_envelope_offer_constraints (
	baseline_envelope_offer_constraint_id TEXT NOT NULL, 
	baseline_envelope_revision_id TEXT NOT NULL, 
	constraint_index INTEGER NOT NULL, 
	official_match_no TEXT NOT NULL, 
	market_code TEXT NOT NULL, 
	omission_allowed INTEGER NOT NULL, 
	PRIMARY KEY (baseline_envelope_offer_constraint_id), 
	CONSTRAINT ck_baseline_offer_constraint_index CHECK (constraint_index >= 0), 
	CONSTRAINT ck_baseline_offer_omission CHECK (omission_allowed IN (0, 1)), 
	CONSTRAINT uq_baseline_offer_constraint_index UNIQUE (baseline_envelope_revision_id, constraint_index), 
	CONSTRAINT uq_baseline_offer_constraint UNIQUE (baseline_envelope_revision_id, official_match_no, market_code), 
	FOREIGN KEY(baseline_envelope_revision_id) REFERENCES operator_baseline_envelope_revisions (baseline_envelope_revision_id) ON DELETE RESTRICT
);

-- table operator_baseline_envelope_revisions
CREATE TABLE operator_baseline_envelope_revisions (
	baseline_envelope_revision_id TEXT NOT NULL, 
	baseline_envelope_family_id TEXT NOT NULL, 
	revision_no INTEGER NOT NULL, 
	supersedes_revision_id TEXT, 
	task_family_id TEXT NOT NULL, 
	work_item_id TEXT NOT NULL, 
	task_snapshot_hash TEXT NOT NULL, 
	slate_revision_id TEXT NOT NULL, 
	task_evidence_bundle_revision_id TEXT NOT NULL, 
	ticket_kind TEXT NOT NULL, 
	capital_cap_minor INTEGER NOT NULL, 
	currency TEXT NOT NULL, 
	maximum_ticket_count INTEGER NOT NULL, 
	maximum_exhaustive_candidate_count INTEGER NOT NULL, 
	content_hash TEXT NOT NULL, 
	action_id TEXT NOT NULL, 
	created_at TEXT NOT NULL, 
	PRIMARY KEY (baseline_envelope_revision_id), 
	CONSTRAINT ck_baseline_envelope_revision CHECK (revision_no >= 1), 
	CONSTRAINT ck_baseline_envelope_cap CHECK (capital_cap_minor >= 0), 
	CONSTRAINT ck_baseline_envelope_ticket_count CHECK (maximum_ticket_count > 0), 
	CONSTRAINT ck_baseline_envelope_enumeration_count CHECK (maximum_exhaustive_candidate_count > 0), 
	CONSTRAINT uq_baseline_envelope_revision UNIQUE (baseline_envelope_family_id, revision_no), 
	UNIQUE (supersedes_revision_id), 
	FOREIGN KEY(supersedes_revision_id) REFERENCES operator_baseline_envelope_revisions (baseline_envelope_revision_id) ON DELETE RESTRICT, 
	FOREIGN KEY(slate_revision_id) REFERENCES official_sale_slate_revisions (slate_revision_id) ON DELETE RESTRICT, 
	FOREIGN KEY(task_evidence_bundle_revision_id) REFERENCES operator_task_evidence_bundle_revisions (task_evidence_bundle_revision_id) ON DELETE RESTRICT, 
	UNIQUE (action_id), 
	FOREIGN KEY(action_id) REFERENCES actions (action_id) ON DELETE RESTRICT
);

-- table operator_baseline_envelope_structure_templates
CREATE TABLE operator_baseline_envelope_structure_templates (
	baseline_envelope_structure_template_id TEXT NOT NULL, 
	baseline_envelope_revision_id TEXT NOT NULL, 
	template_index INTEGER NOT NULL, 
	kind TEXT NOT NULL, 
	structure_code TEXT NOT NULL, 
	pass_size INTEGER, 
	required_offer_count INTEGER NOT NULL, 
	maximum_groups INTEGER NOT NULL, 
	PRIMARY KEY (baseline_envelope_structure_template_id), 
	CONSTRAINT ck_baseline_structure_template_index CHECK (template_index >= 0), 
	CONSTRAINT ck_baseline_pass_size CHECK (pass_size IS NULL OR pass_size > 0), 
	CONSTRAINT ck_baseline_structure_template_counts CHECK (required_offer_count > 0 AND maximum_groups > 0), 
	CONSTRAINT uq_baseline_structure_template_index UNIQUE (baseline_envelope_revision_id, template_index), 
	CONSTRAINT uq_baseline_structure_template_code UNIQUE (baseline_envelope_revision_id, structure_code), 
	FOREIGN KEY(baseline_envelope_revision_id) REFERENCES operator_baseline_envelope_revisions (baseline_envelope_revision_id) ON DELETE RESTRICT
);

-- table operator_baseline_envelope_template_offers
CREATE TABLE operator_baseline_envelope_template_offers (
	baseline_envelope_template_offer_id TEXT NOT NULL, 
	baseline_envelope_structure_template_id TEXT NOT NULL, 
	offer_index INTEGER NOT NULL, 
	official_match_no TEXT NOT NULL, 
	PRIMARY KEY (baseline_envelope_template_offer_id), 
	CONSTRAINT ck_baseline_template_offer_index CHECK (offer_index >= 0), 
	CONSTRAINT uq_baseline_template_offer_index UNIQUE (baseline_envelope_structure_template_id, offer_index), 
	CONSTRAINT uq_baseline_template_offer_number UNIQUE (baseline_envelope_structure_template_id, official_match_no), 
	FOREIGN KEY(baseline_envelope_structure_template_id) REFERENCES operator_baseline_envelope_structure_templates (baseline_envelope_structure_template_id) ON DELETE RESTRICT
);

-- table operator_candidate_audit_findings
CREATE TABLE operator_candidate_audit_findings (
	candidate_audit_finding_id TEXT NOT NULL, 
	candidate_revision_id TEXT NOT NULL, 
	finding_index INTEGER NOT NULL, 
	audit_kind TEXT NOT NULL, 
	finding_code TEXT NOT NULL, 
	severity TEXT NOT NULL, 
	message TEXT NOT NULL, 
	official_match_no TEXT, 
	rule_id TEXT, 
	PRIMARY KEY (candidate_audit_finding_id), 
	CONSTRAINT ck_operator_candidate_finding_index CHECK (finding_index >= 0), 
	CONSTRAINT ck_operator_candidate_audit_kind CHECK (audit_kind IN ('legs', 'prescription_difference', 'budget', 'deployment')), 
	CONSTRAINT ck_operator_candidate_audit_severity CHECK (severity IN ('WARN', 'ERROR')), 
	CONSTRAINT uq_operator_candidate_finding_index UNIQUE (candidate_revision_id, finding_index), 
	FOREIGN KEY(candidate_revision_id) REFERENCES operator_candidates (candidate_revision_id) ON DELETE RESTRICT
);

-- table operator_candidate_band_outcomes
CREATE TABLE operator_candidate_band_outcomes (
	candidate_band_outcome_id TEXT NOT NULL, 
	candidate_set_revision_id TEXT NOT NULL, 
	odds_band TEXT NOT NULL, 
	status TEXT NOT NULL, 
	candidate_count INTEGER NOT NULL, 
	reason_code TEXT, 
	PRIMARY KEY (candidate_band_outcome_id), 
	CONSTRAINT ck_operator_candidate_band_outcome_band CHECK (odds_band IN ('10x', '20x', '50x', '100x')), 
	CONSTRAINT ck_operator_candidate_band_outcome_shape CHECK ((status = 'candidates' AND candidate_count > 0 AND reason_code IS NULL) OR (status = 'no_feasible_candidate' AND candidate_count = 0 AND length(trim(reason_code)) > 0)), 
	CONSTRAINT uq_operator_candidate_band_outcome UNIQUE (candidate_set_revision_id, odds_band), 
	FOREIGN KEY(candidate_set_revision_id) REFERENCES operator_candidate_set_revisions (candidate_set_revision_id) ON DELETE RESTRICT
);

-- table operator_candidate_dead_faces
CREATE TABLE operator_candidate_dead_faces (
	candidate_dead_face_id TEXT NOT NULL, 
	candidate_revision_id TEXT NOT NULL, 
	dead_face_index INTEGER NOT NULL, 
	official_match_no TEXT NOT NULL, 
	face_code TEXT NOT NULL, 
	PRIMARY KEY (candidate_dead_face_id), 
	CONSTRAINT ck_operator_candidate_dead_face_index CHECK (dead_face_index >= 0), 
	CONSTRAINT uq_operator_candidate_dead_face_index UNIQUE (candidate_revision_id, dead_face_index), 
	CONSTRAINT uq_operator_candidate_dead_face UNIQUE (candidate_revision_id, official_match_no, face_code), 
	FOREIGN KEY(candidate_revision_id) REFERENCES operator_candidates (candidate_revision_id) ON DELETE RESTRICT
);

-- table operator_candidate_generation_override_links
CREATE TABLE operator_candidate_generation_override_links (
	candidate_generation_override_link_id TEXT NOT NULL, 
	generation_request_id TEXT NOT NULL, 
	link_index INTEGER NOT NULL, 
	override_receipt_id TEXT NOT NULL, 
	created_at TEXT NOT NULL, 
	PRIMARY KEY (candidate_generation_override_link_id), 
	CONSTRAINT ck_operator_candidate_generation_override_link_index CHECK (link_index >= 0), 
	CONSTRAINT uq_operator_candidate_generation_override_link_index UNIQUE (generation_request_id, link_index), 
	FOREIGN KEY(generation_request_id) REFERENCES operator_candidate_generation_requests (generation_request_id) ON DELETE RESTRICT, 
	UNIQUE (override_receipt_id), 
	FOREIGN KEY(override_receipt_id) REFERENCES operator_ticket_audit_override_receipts (ticket_audit_override_receipt_id) ON DELETE RESTRICT
);

-- table operator_candidate_generation_requests
CREATE TABLE operator_candidate_generation_requests (
	generation_request_id TEXT NOT NULL, 
	action_id TEXT NOT NULL, 
	task_family_id TEXT NOT NULL, 
	work_item_id TEXT NOT NULL, 
	task_snapshot_hash TEXT NOT NULL, 
	slate_revision_id TEXT NOT NULL, 
	task_evidence_bundle_revision_id TEXT NOT NULL, 
	market_prior_baseline_revision_id TEXT NOT NULL, 
	baseline_envelope_revision_id TEXT NOT NULL, 
	judgment_prescription_revision_id TEXT NOT NULL, 
	fixed_prize_policy_revision_id TEXT, 
	dependency_fingerprint TEXT NOT NULL, 
	expected_current_revision_no INTEGER NOT NULL, 
	content_hash TEXT NOT NULL, 
	requested_at TEXT NOT NULL, 
	PRIMARY KEY (generation_request_id), 
	CONSTRAINT ck_operator_candidate_generation_expected_revision CHECK (expected_current_revision_no >= 0), 
	CONSTRAINT uq_operator_candidate_generation_request UNIQUE (task_family_id, work_item_id, content_hash), 
	UNIQUE (action_id), 
	FOREIGN KEY(action_id) REFERENCES actions (action_id) ON DELETE RESTRICT, 
	FOREIGN KEY(slate_revision_id) REFERENCES official_sale_slate_revisions (slate_revision_id) ON DELETE RESTRICT, 
	FOREIGN KEY(task_evidence_bundle_revision_id) REFERENCES operator_task_evidence_bundle_revisions (task_evidence_bundle_revision_id) ON DELETE RESTRICT, 
	FOREIGN KEY(market_prior_baseline_revision_id) REFERENCES operator_market_prior_baseline_revisions (market_prior_baseline_revision_id) ON DELETE RESTRICT, 
	FOREIGN KEY(baseline_envelope_revision_id) REFERENCES operator_baseline_envelope_revisions (baseline_envelope_revision_id) ON DELETE RESTRICT, 
	FOREIGN KEY(judgment_prescription_revision_id) REFERENCES operator_judgment_prescription_revisions (judgment_prescription_revision_id) ON DELETE RESTRICT, 
	FOREIGN KEY(fixed_prize_policy_revision_id) REFERENCES zucai_fixed_prize_policy_revisions (fixed_prize_policy_revision_id) ON DELETE RESTRICT
);

-- table operator_candidate_metrics
CREATE TABLE operator_candidate_metrics (
	candidate_metric_id TEXT NOT NULL, 
	candidate_revision_id TEXT NOT NULL, 
	currency TEXT NOT NULL, 
	ticket_count INTEGER NOT NULL, 
	distinct_note_count INTEGER NOT NULL, 
	paid_note_unit_count INTEGER NOT NULL, 
	stake_minor INTEGER NOT NULL, 
	capital_utilization_decimal TEXT NOT NULL, 
	probability_kind TEXT NOT NULL, 
	objective_probability_decimal TEXT NOT NULL, 
	expected_broken_legs_decimal TEXT NOT NULL, 
	break_even_bonus_minor INTEGER, 
	break_even_to_official_median_decimal TEXT, 
	PRIMARY KEY (candidate_metric_id), 
	CONSTRAINT ck_operator_candidate_metric_currency CHECK (length(currency) = 3), 
	CONSTRAINT ck_operator_candidate_metric_counts CHECK (ticket_count > 0 AND distinct_note_count > 0 AND paid_note_unit_count > 0 AND stake_minor > 0), 
	CONSTRAINT ck_operator_candidate_probability_kind CHECK (probability_kind IN ('all_required_legs', 'any_ticket_all_required_legs')), 
	CONSTRAINT ck_operator_candidate_capital_utilization CHECK (typeof(capital_utilization_decimal) = 'text' AND printf('%.12f', CAST(capital_utilization_decimal AS REAL)) = capital_utilization_decimal AND CAST(capital_utilization_decimal AS REAL) >= 0.0), 
	CONSTRAINT ck_operator_candidate_objective_probability CHECK (typeof(objective_probability_decimal) = 'text' AND printf('%.12f', CAST(objective_probability_decimal AS REAL)) = objective_probability_decimal AND CAST(objective_probability_decimal AS REAL) BETWEEN 0.0 AND 1.0), 
	CONSTRAINT ck_operator_candidate_expected_broken_legs CHECK (typeof(expected_broken_legs_decimal) = 'text' AND printf('%.12f', CAST(expected_broken_legs_decimal AS REAL)) = expected_broken_legs_decimal AND CAST(expected_broken_legs_decimal AS REAL) >= 0.0), 
	CONSTRAINT ck_operator_candidate_break_even CHECK (break_even_bonus_minor IS NULL OR break_even_bonus_minor >= 0), 
	CONSTRAINT ck_operator_candidate_median_multiple CHECK (break_even_to_official_median_decimal IS NULL OR typeof(break_even_to_official_median_decimal) = 'text' AND printf('%.12f', CAST(break_even_to_official_median_decimal AS REAL)) = break_even_to_official_median_decimal AND CAST(break_even_to_official_median_decimal AS REAL) >= 0.0), 
	UNIQUE (candidate_revision_id), 
	FOREIGN KEY(candidate_revision_id) REFERENCES operator_candidates (candidate_revision_id) ON DELETE RESTRICT
);

-- table operator_candidate_selections
CREATE TABLE operator_candidate_selections (
	candidate_selection_id TEXT NOT NULL, 
	candidate_selection_family_id TEXT NOT NULL, 
	revision_no INTEGER NOT NULL, 
	supersedes_revision_id TEXT, 
	candidate_set_revision_id TEXT NOT NULL, 
	candidate_revision_id TEXT NOT NULL, 
	task_family_id TEXT NOT NULL, 
	work_item_id TEXT NOT NULL, 
	task_snapshot_hash TEXT NOT NULL, 
	slate_revision_id TEXT NOT NULL, 
	reason TEXT NOT NULL, 
	content_hash TEXT NOT NULL, 
	action_id TEXT NOT NULL, 
	selected_at TEXT NOT NULL, 
	PRIMARY KEY (candidate_selection_id), 
	CONSTRAINT ck_operator_candidate_selection_revision_positive CHECK (revision_no >= 1), 
	CONSTRAINT ck_operator_candidate_selection_reason CHECK (length(trim(reason)) > 0), 
	CONSTRAINT uq_operator_candidate_selection_family_revision UNIQUE (candidate_selection_family_id, revision_no), 
	UNIQUE (supersedes_revision_id), 
	FOREIGN KEY(supersedes_revision_id) REFERENCES operator_candidate_selections (candidate_selection_id) ON DELETE RESTRICT, 
	FOREIGN KEY(candidate_set_revision_id) REFERENCES operator_candidate_set_revisions (candidate_set_revision_id) ON DELETE RESTRICT, 
	FOREIGN KEY(candidate_revision_id) REFERENCES operator_candidates (candidate_revision_id) ON DELETE RESTRICT, 
	FOREIGN KEY(slate_revision_id) REFERENCES official_sale_slate_revisions (slate_revision_id) ON DELETE RESTRICT, 
	UNIQUE (action_id), 
	FOREIGN KEY(action_id) REFERENCES actions (action_id) ON DELETE RESTRICT
);

-- table operator_candidate_set_revisions
CREATE TABLE operator_candidate_set_revisions (
	candidate_set_revision_id TEXT NOT NULL, 
	candidate_set_family_id TEXT NOT NULL, 
	revision_no INTEGER NOT NULL, 
	supersedes_revision_id TEXT, 
	generation_request_id TEXT NOT NULL, 
	task_family_id TEXT NOT NULL, 
	work_item_id TEXT NOT NULL, 
	task_snapshot_hash TEXT NOT NULL, 
	slate_revision_id TEXT NOT NULL, 
	market_prior_baseline_revision_id TEXT NOT NULL, 
	baseline_envelope_revision_id TEXT NOT NULL, 
	judgment_prescription_revision_id TEXT NOT NULL, 
	set_kind TEXT NOT NULL, 
	comparison_only INTEGER NOT NULL, 
	generator_version TEXT NOT NULL, 
	audit_policy_version TEXT NOT NULL, 
	candidate_count INTEGER NOT NULL, 
	eligible_count INTEGER NOT NULL, 
	audit_blocked_count INTEGER NOT NULL, 
	over_cap_count INTEGER NOT NULL, 
	change_delta_json TEXT, 
	rationale TEXT, 
	content_hash TEXT NOT NULL, 
	action_id TEXT NOT NULL, 
	created_at TEXT NOT NULL, 
	PRIMARY KEY (candidate_set_revision_id), 
	CONSTRAINT ck_operator_candidate_set_revision CHECK (revision_no >= 1), 
	CONSTRAINT ck_operator_candidate_set_kind CHECK (set_kind IN ('judgment_bound', 'conditional_market_counterfactual')), 
	CONSTRAINT ck_operator_candidate_set_comparison CHECK ((set_kind = 'judgment_bound' AND comparison_only = 0) OR (set_kind = 'conditional_market_counterfactual' AND comparison_only = 1)), 
	CONSTRAINT ck_operator_candidate_set_counts CHECK (candidate_count >= 0 AND eligible_count >= 0 AND audit_blocked_count >= 0 AND over_cap_count >= 0 AND candidate_count = eligible_count + audit_blocked_count + over_cap_count), 
	CONSTRAINT ck_operator_candidate_set_iteration_shape CHECK ((supersedes_revision_id IS NULL AND change_delta_json IS NULL AND rationale IS NULL) OR (supersedes_revision_id IS NOT NULL AND change_delta_json IS NOT NULL AND length(trim(rationale)) > 0)), 
	CONSTRAINT uq_operator_candidate_set_revision UNIQUE (candidate_set_family_id, revision_no), 
	CONSTRAINT uq_operator_candidate_set_request_kind UNIQUE (generation_request_id, set_kind), 
	UNIQUE (supersedes_revision_id), 
	FOREIGN KEY(supersedes_revision_id) REFERENCES operator_candidate_set_revisions (candidate_set_revision_id) ON DELETE RESTRICT, 
	FOREIGN KEY(generation_request_id) REFERENCES operator_candidate_generation_requests (generation_request_id) ON DELETE RESTRICT, 
	FOREIGN KEY(slate_revision_id) REFERENCES official_sale_slate_revisions (slate_revision_id) ON DELETE RESTRICT, 
	FOREIGN KEY(market_prior_baseline_revision_id) REFERENCES operator_market_prior_baseline_revisions (market_prior_baseline_revision_id) ON DELETE RESTRICT, 
	FOREIGN KEY(baseline_envelope_revision_id) REFERENCES operator_baseline_envelope_revisions (baseline_envelope_revision_id) ON DELETE RESTRICT, 
	FOREIGN KEY(judgment_prescription_revision_id) REFERENCES operator_judgment_prescription_revisions (judgment_prescription_revision_id) ON DELETE RESTRICT, 
	FOREIGN KEY(action_id) REFERENCES actions (action_id) ON DELETE RESTRICT
);

-- table operator_candidate_ticket_legs
CREATE TABLE operator_candidate_ticket_legs (
	candidate_ticket_leg_id TEXT NOT NULL, 
	candidate_ticket_id TEXT NOT NULL, 
	leg_index INTEGER NOT NULL, 
	official_offer_revision_id TEXT NOT NULL, 
	match_id TEXT NOT NULL, 
	market_definition_id TEXT NOT NULL, 
	selection_code TEXT NOT NULL, 
	quote_id TEXT, 
	booked_decimal_odds TEXT, 
	settlement_parameter_decimal TEXT, 
	PRIMARY KEY (candidate_ticket_leg_id), 
	CONSTRAINT ck_operator_candidate_leg_index CHECK (leg_index >= 0), 
	CONSTRAINT ck_operator_candidate_leg_odds CHECK (booked_decimal_odds IS NULL OR typeof(booked_decimal_odds) = 'text' AND printf('%.12f', CAST(booked_decimal_odds AS REAL)) = booked_decimal_odds AND CAST(booked_decimal_odds AS REAL) > 0.0), 
	CONSTRAINT ck_operator_candidate_leg_parameter CHECK (settlement_parameter_decimal IS NULL OR typeof(settlement_parameter_decimal) = 'text' AND printf('%.12f', CAST(settlement_parameter_decimal AS REAL)) = settlement_parameter_decimal ), 
	CONSTRAINT ck_operator_candidate_leg_quote_shape CHECK ((quote_id IS NULL AND booked_decimal_odds IS NULL AND settlement_parameter_decimal IS NULL) OR (quote_id IS NOT NULL AND booked_decimal_odds IS NOT NULL)), 
	CONSTRAINT uq_operator_candidate_leg_index UNIQUE (candidate_ticket_id, leg_index), 
	CONSTRAINT uq_operator_candidate_leg_selection UNIQUE (candidate_ticket_id, official_offer_revision_id, market_definition_id, selection_code), 
	FOREIGN KEY(candidate_ticket_id) REFERENCES operator_candidate_tickets (candidate_ticket_id) ON DELETE RESTRICT, 
	FOREIGN KEY(official_offer_revision_id) REFERENCES official_offer_revisions (official_offer_revision_id) ON DELETE RESTRICT, 
	FOREIGN KEY(match_id) REFERENCES matches (match_id) ON DELETE RESTRICT, 
	FOREIGN KEY(market_definition_id) REFERENCES market_definitions (market_definition_id) ON DELETE RESTRICT, 
	FOREIGN KEY(quote_id) REFERENCES market_quotes (quote_id) ON DELETE RESTRICT
);

-- table operator_candidate_tickets
CREATE TABLE operator_candidate_tickets (
	candidate_ticket_id TEXT NOT NULL, 
	candidate_revision_id TEXT NOT NULL, 
	ticket_index INTEGER NOT NULL, 
	ticket_kind TEXT NOT NULL, 
	structure_code TEXT NOT NULL, 
	group_code TEXT, 
	currency TEXT NOT NULL, 
	unit_stake_minor INTEGER NOT NULL, 
	unit_count INTEGER NOT NULL, 
	stake_minor INTEGER NOT NULL, 
	composition_hash TEXT NOT NULL, 
	fixed_prize_policy_revision_id TEXT, 
	PRIMARY KEY (candidate_ticket_id), 
	CONSTRAINT ck_operator_candidate_ticket_index CHECK (ticket_index >= 0), 
	CONSTRAINT ck_operator_candidate_ticket_kind CHECK (ticket_kind IN ('jczq_pass', 'sfc', 'renjiu')), 
	CONSTRAINT ck_operator_candidate_ticket_currency CHECK (length(currency) = 3), 
	CONSTRAINT ck_operator_candidate_ticket_stake CHECK (unit_stake_minor > 0 AND unit_count > 0 AND stake_minor = unit_stake_minor * unit_count), 
	CONSTRAINT ck_operator_candidate_ticket_policy CHECK ((ticket_kind = 'jczq_pass' AND fixed_prize_policy_revision_id IS NULL) OR (ticket_kind IN ('sfc', 'renjiu') AND fixed_prize_policy_revision_id IS NOT NULL)), 
	CONSTRAINT uq_operator_candidate_ticket_index UNIQUE (candidate_revision_id, ticket_index), 
	CONSTRAINT uq_operator_candidate_ticket_composition UNIQUE (candidate_revision_id, composition_hash), 
	FOREIGN KEY(candidate_revision_id) REFERENCES operator_candidates (candidate_revision_id) ON DELETE RESTRICT, 
	FOREIGN KEY(fixed_prize_policy_revision_id) REFERENCES zucai_fixed_prize_policy_revisions (fixed_prize_policy_revision_id) ON DELETE RESTRICT
);

-- table operator_candidates
CREATE TABLE operator_candidates (
	candidate_revision_id TEXT NOT NULL, 
	candidate_set_revision_id TEXT NOT NULL, 
	candidate_index INTEGER NOT NULL, 
	candidate_code TEXT NOT NULL, 
	partition TEXT NOT NULL, 
	rank INTEGER, 
	eligible INTEGER NOT NULL, 
	deployable INTEGER NOT NULL, 
	leg_audit_completed INTEGER NOT NULL, 
	prescription_audit_completed INTEGER NOT NULL, 
	budget_check_completed INTEGER NOT NULL, 
	deployment_report_completed INTEGER NOT NULL, 
	content_hash TEXT NOT NULL, 
	odds_band TEXT, 
	target_odds_min_decimal TEXT, 
	target_odds_max_decimal TEXT, 
	combined_decimal_odds TEXT, 
	parent_candidate_revision_id TEXT, 
	delta_reason TEXT, 
	PRIMARY KEY (candidate_revision_id), 
	CONSTRAINT ck_operator_candidate_index CHECK (candidate_index >= 0), 
	CONSTRAINT ck_operator_candidate_partition CHECK (partition IN ('eligible', 'audit_blocked', 'over_cap')), 
	CONSTRAINT ck_operator_candidate_eligible CHECK ((partition = 'eligible' AND eligible = 1) OR (partition != 'eligible' AND eligible = 0)), 
	CONSTRAINT ck_operator_candidate_rank CHECK ((partition = 'eligible' AND rank IS NOT NULL AND rank > 0) OR (partition != 'eligible' AND rank IS NULL)), 
	CONSTRAINT ck_operator_candidate_deployability CHECK (eligible IN (0, 1) AND deployable IN (0, 1) AND deployable <= eligible), 
	CONSTRAINT ck_operator_candidate_all_audits CHECK (leg_audit_completed = 1 AND prescription_audit_completed = 1 AND budget_check_completed = 1 AND deployment_report_completed = 1), 
	CONSTRAINT ck_operator_candidate_odds_band_shape CHECK ((odds_band IS NULL AND target_odds_min_decimal IS NULL AND target_odds_max_decimal IS NULL AND combined_decimal_odds IS NULL) OR (odds_band IN ('10x', '20x', '50x', '100x') AND target_odds_min_decimal IS NOT NULL AND target_odds_max_decimal IS NOT NULL AND combined_decimal_odds IS NOT NULL)), 
	CONSTRAINT ck_operator_candidate_iteration_shape CHECK ((parent_candidate_revision_id IS NULL AND delta_reason IS NULL) OR (parent_candidate_revision_id IS NOT NULL AND length(trim(delta_reason)) > 0)), 
	CONSTRAINT uq_operator_candidate_index UNIQUE (candidate_set_revision_id, candidate_index), 
	CONSTRAINT uq_operator_candidate_code UNIQUE (candidate_set_revision_id, candidate_code), 
	CONSTRAINT uq_operator_candidate_content UNIQUE (candidate_set_revision_id, content_hash), 
	FOREIGN KEY(candidate_set_revision_id) REFERENCES operator_candidate_set_revisions (candidate_set_revision_id) ON DELETE RESTRICT
);

-- table operator_confirmation_challenge_heads
CREATE TABLE operator_confirmation_challenge_heads (
	ticket_artifact_id TEXT NOT NULL, 
	challenge_revision_id TEXT NOT NULL, 
	challenge_family_id TEXT NOT NULL, 
	revision_no INTEGER NOT NULL, 
	updated_at TEXT NOT NULL, 
	PRIMARY KEY (ticket_artifact_id), 
	CONSTRAINT ck_operator_confirmation_challenge_head_revision_positive CHECK (revision_no >= 1), 
	FOREIGN KEY(ticket_artifact_id) REFERENCES audited_ticket_artifacts (ticket_artifact_id) ON DELETE RESTRICT, 
	UNIQUE (challenge_revision_id), 
	FOREIGN KEY(challenge_revision_id) REFERENCES operator_confirmation_challenge_revisions (challenge_revision_id) ON DELETE RESTRICT
);

-- table operator_confirmation_challenge_revisions
CREATE TABLE operator_confirmation_challenge_revisions (
	challenge_revision_id TEXT NOT NULL, 
	challenge_family_id TEXT NOT NULL, 
	legacy_confirmation_id TEXT, 
	revision_no INTEGER NOT NULL, 
	supersedes_revision_id TEXT, 
	ticket_artifact_id TEXT NOT NULL, 
	artifact_composition_hash TEXT NOT NULL, 
	lineage_revision_id TEXT NOT NULL, 
	nonce_hash TEXT NOT NULL, 
	issued_at TEXT NOT NULL, 
	effective_cutoff_at TEXT NOT NULL, 
	action_id TEXT NOT NULL, legacy_expires_at TEXT, 
	PRIMARY KEY (challenge_revision_id), 
	CONSTRAINT ck_operator_confirmation_challenge_revision_positive CHECK (revision_no >= 1), 
	CONSTRAINT uq_operator_confirmation_challenge_family_revision UNIQUE (challenge_family_id, revision_no), 
	UNIQUE (legacy_confirmation_id), 
	UNIQUE (supersedes_revision_id), 
	FOREIGN KEY(supersedes_revision_id) REFERENCES operator_confirmation_challenge_revisions (challenge_revision_id) ON DELETE RESTRICT, 
	FOREIGN KEY(ticket_artifact_id) REFERENCES audited_ticket_artifacts (ticket_artifact_id) ON DELETE RESTRICT, 
	FOREIGN KEY(lineage_revision_id) REFERENCES operator_ticket_decision_lineage_revisions (lineage_revision_id) ON DELETE RESTRICT, 
	UNIQUE (nonce_hash), 
	FOREIGN KEY(action_id) REFERENCES actions (action_id) ON DELETE RESTRICT
);

-- table operator_evidence_coverage_receipts
CREATE TABLE operator_evidence_coverage_receipts (
	coverage_receipt_id TEXT NOT NULL, 
	intake_receipt_id TEXT NOT NULL, 
	match_id TEXT NOT NULL, 
	requirement_id TEXT NOT NULL, 
	subject_scope TEXT NOT NULL, 
	evidence_ref_tokens_json TEXT NOT NULL, 
	PRIMARY KEY (coverage_receipt_id), 
	CONSTRAINT ck_operator_evidence_requirement CHECK (requirement_id IN ('E1', 'E2', 'E3', 'E4', 'E5', 'E6a', 'E6b', 'EC')), 
	CONSTRAINT uq_operator_evidence_coverage_scope UNIQUE (intake_receipt_id, match_id, requirement_id, subject_scope), 
	FOREIGN KEY(intake_receipt_id) REFERENCES operator_evidence_intake_receipts (intake_receipt_id) ON DELETE RESTRICT, 
	FOREIGN KEY(match_id) REFERENCES matches (match_id) ON DELETE RESTRICT
);

-- table operator_evidence_freeze_requests
CREATE TABLE operator_evidence_freeze_requests (
	evidence_freeze_request_id TEXT NOT NULL, 
	action_id TEXT NOT NULL, 
	task_family_id TEXT NOT NULL, 
	lane TEXT NOT NULL, 
	business_key TEXT NOT NULL, 
	slate_revision_id TEXT NOT NULL, 
	task_snapshot_hash TEXT NOT NULL, 
	requirement_revision_token TEXT NOT NULL, 
	information_cutoff_at TEXT NOT NULL, 
	policy_version TEXT NOT NULL, 
	dependency_fingerprint TEXT NOT NULL, 
	requested_at TEXT NOT NULL, 
	PRIMARY KEY (evidence_freeze_request_id), 
	CONSTRAINT ck_evidence_freeze_request_lane CHECK (lane IN ('jczq', 'zucai')), 
	CONSTRAINT uq_evidence_freeze_request_dependencies UNIQUE (task_family_id, dependency_fingerprint), 
	UNIQUE (action_id), 
	FOREIGN KEY(action_id) REFERENCES actions (action_id) ON DELETE RESTRICT, 
	FOREIGN KEY(slate_revision_id) REFERENCES official_sale_slate_revisions (slate_revision_id) ON DELETE RESTRICT, 
	FOREIGN KEY(policy_version) REFERENCES policy_versions (policy_version_id) ON DELETE RESTRICT
);

-- table operator_evidence_intake_objects
CREATE TABLE operator_evidence_intake_objects (
	intake_object_id TEXT NOT NULL, 
	intake_receipt_id TEXT NOT NULL, 
	match_id TEXT NOT NULL, 
	object_kind TEXT NOT NULL, 
	object_id TEXT NOT NULL, 
	object_index INTEGER NOT NULL, 
	observed_at TEXT NOT NULL, 
	source_retrieval_ids_json TEXT NOT NULL, 
	source_kinds_json TEXT NOT NULL, 
	PRIMARY KEY (intake_object_id), 
	CONSTRAINT ck_operator_evidence_object_kind CHECK (object_kind IN ('observation', 'claim')), 
	CONSTRAINT ck_operator_evidence_object_index CHECK (object_index >= 0), 
	CONSTRAINT uq_operator_evidence_intake_object UNIQUE (intake_receipt_id, object_kind, object_id), 
	CONSTRAINT uq_operator_evidence_intake_ordinal UNIQUE (intake_receipt_id, object_index), 
	FOREIGN KEY(intake_receipt_id) REFERENCES operator_evidence_intake_receipts (intake_receipt_id) ON DELETE RESTRICT, 
	FOREIGN KEY(match_id) REFERENCES matches (match_id) ON DELETE RESTRICT
);

-- table operator_evidence_intake_receipts
CREATE TABLE operator_evidence_intake_receipts (
	intake_receipt_id TEXT NOT NULL, 
	action_id TEXT NOT NULL, 
	lane TEXT NOT NULL, 
	business_key TEXT NOT NULL, 
	slate_revision_id TEXT NOT NULL, 
	task_snapshot_hash TEXT NOT NULL, 
	captured_at TEXT NOT NULL, 
	manifest_sha256 TEXT NOT NULL, 
	source_retrieval_ids_json TEXT NOT NULL, 
	committed_count INTEGER NOT NULL, 
	rejected_count INTEGER NOT NULL, 
	skipped_count INTEGER NOT NULL, 
	persisted_count INTEGER NOT NULL, 
	created_at TEXT NOT NULL, 
	PRIMARY KEY (intake_receipt_id), 
	CONSTRAINT ck_operator_evidence_lane CHECK (lane IN ('jczq', 'zucai')), 
	CONSTRAINT ck_operator_evidence_counts_nonnegative CHECK (committed_count >= 0 AND rejected_count >= 0 AND skipped_count >= 0 AND persisted_count >= 0), 
	CONSTRAINT ck_operator_evidence_counts_reconciled CHECK (committed_count = persisted_count AND rejected_count = 0 AND skipped_count = 0), 
	UNIQUE (action_id), 
	FOREIGN KEY(action_id) REFERENCES actions (action_id) ON DELETE RESTRICT, 
	FOREIGN KEY(slate_revision_id) REFERENCES official_sale_slate_revisions (slate_revision_id) ON DELETE RESTRICT, 
	UNIQUE (manifest_sha256)
);

-- table operator_jczq_board_research_state_revisions
CREATE TABLE operator_jczq_board_research_state_revisions (
	board_research_state_id TEXT NOT NULL, 
	board_research_family_id TEXT NOT NULL, 
	revision_no INTEGER NOT NULL, 
	supersedes_revision_id TEXT, 
	business_date TEXT NOT NULL, 
	match_id TEXT NOT NULL, 
	official_match_no TEXT NOT NULL, 
	status TEXT NOT NULL, 
	source_run_id TEXT, 
	artifact_id TEXT, 
	captured_at TEXT, 
	kickoff_at TEXT NOT NULL, 
	historical_replay INTEGER NOT NULL, 
	action_id TEXT NOT NULL, 
	created_at TEXT NOT NULL, 
	PRIMARY KEY (board_research_state_id), 
	CONSTRAINT ck_jczq_board_research_revision_no CHECK (revision_no >= 1), 
	CONSTRAINT ck_jczq_board_research_revision_status CHECK (status IN ('researched', 'price_only', 'rejected')), 
	CONSTRAINT ck_jczq_board_research_revision_lineage CHECK ((status = 'researched' AND source_run_id IS NOT NULL AND artifact_id IS NOT NULL AND captured_at IS NOT NULL) OR status IN ('price_only', 'rejected')), 
	CONSTRAINT ck_jczq_board_research_revision_replay CHECK (historical_replay IN (0, 1)), 
	CONSTRAINT uq_jczq_board_research_family_revision UNIQUE (board_research_family_id, revision_no), 
	FOREIGN KEY(supersedes_revision_id) REFERENCES operator_jczq_board_research_state_revisions (board_research_state_id) ON DELETE RESTRICT, 
	FOREIGN KEY(source_run_id) REFERENCES source_runs (source_run_id) ON DELETE RESTRICT, 
	FOREIGN KEY(artifact_id) REFERENCES source_artifacts (artifact_id) ON DELETE RESTRICT, 
	FOREIGN KEY(action_id) REFERENCES actions (action_id) ON DELETE RESTRICT
);

-- table operator_jczq_board_research_states
CREATE TABLE operator_jczq_board_research_states (
	board_research_state_id TEXT NOT NULL, 
	business_date TEXT NOT NULL, 
	match_id TEXT NOT NULL, 
	official_match_no TEXT NOT NULL, 
	status TEXT NOT NULL, 
	source_run_id TEXT, 
	artifact_id TEXT, 
	captured_at TEXT, 
	kickoff_at TEXT NOT NULL, 
	historical_replay INTEGER NOT NULL, 
	action_id TEXT NOT NULL, 
	created_at TEXT NOT NULL, 
	PRIMARY KEY (board_research_state_id), 
	CONSTRAINT ck_operator_jczq_board_research_status CHECK (status IN ('researched', 'price_only', 'rejected')), 
	CONSTRAINT ck_operator_jczq_board_research_lineage CHECK ((status = 'researched' AND source_run_id IS NOT NULL AND artifact_id IS NOT NULL AND captured_at IS NOT NULL) OR status IN ('price_only', 'rejected')), 
	CONSTRAINT ck_operator_jczq_board_research_replay CHECK (historical_replay IN (0, 1)), 
	CONSTRAINT uq_operator_jczq_board_research_match UNIQUE (business_date, match_id), 
	CONSTRAINT uq_operator_jczq_board_research_number UNIQUE (business_date, official_match_no), 
	FOREIGN KEY(source_run_id) REFERENCES source_runs (source_run_id) ON DELETE RESTRICT, 
	FOREIGN KEY(artifact_id) REFERENCES source_artifacts (artifact_id) ON DELETE RESTRICT, 
	FOREIGN KEY(action_id) REFERENCES actions (action_id) ON DELETE RESTRICT
);

