);

-- table operator_market_prior_baseline_probabilities
CREATE TABLE operator_market_prior_baseline_probabilities (
	market_prior_baseline_probability_id TEXT NOT NULL, 
	market_prior_baseline_revision_id TEXT NOT NULL, 
	item_index INTEGER NOT NULL, 
	match_id TEXT NOT NULL, 
	official_offer_revision_id TEXT NOT NULL, 
	market_definition_id TEXT NOT NULL, 
	face_code TEXT NOT NULL, 
	probability_decimal TEXT NOT NULL, 
	market_snapshot_id TEXT NOT NULL, 
	quote_id TEXT NOT NULL, 
	booked_decimal_odds TEXT NOT NULL, 
	quote_captured_at TEXT NOT NULL, 
	settlement_parameter_decimal TEXT, 
	PRIMARY KEY (market_prior_baseline_probability_id), 
	CONSTRAINT ck_market_prior_probability_index CHECK (item_index >= 0), 
	CONSTRAINT ck_market_prior_probability_canonical CHECK (typeof(probability_decimal) = 'text' AND printf('%.12f', CAST(probability_decimal AS REAL)) = probability_decimal AND CAST(probability_decimal AS REAL) BETWEEN 0.0 AND 1.0), 
	CONSTRAINT ck_market_prior_booked_odds_canonical CHECK (typeof(booked_decimal_odds) = 'text' AND printf('%.12f', CAST(booked_decimal_odds AS REAL)) = booked_decimal_odds AND CAST(booked_decimal_odds AS REAL) > 1.0), 
	CONSTRAINT ck_market_prior_settlement_parameter_canonical CHECK (settlement_parameter_decimal IS NULL OR typeof(settlement_parameter_decimal) = 'text' AND printf('%.12f', CAST(settlement_parameter_decimal AS REAL)) = settlement_parameter_decimal), 
	CONSTRAINT uq_market_prior_probability_index UNIQUE (market_prior_baseline_revision_id, item_index), 
	CONSTRAINT uq_market_prior_probability_face UNIQUE (market_prior_baseline_revision_id, match_id, market_definition_id, face_code), 
	FOREIGN KEY(market_prior_baseline_revision_id) REFERENCES operator_market_prior_baseline_revisions (market_prior_baseline_revision_id) ON DELETE RESTRICT, 
	FOREIGN KEY(match_id) REFERENCES matches (match_id) ON DELETE RESTRICT, 
	FOREIGN KEY(official_offer_revision_id) REFERENCES official_offer_revisions (official_offer_revision_id) ON DELETE RESTRICT, 
	FOREIGN KEY(market_definition_id) REFERENCES market_definitions (market_definition_id) ON DELETE RESTRICT, 
	FOREIGN KEY(market_snapshot_id) REFERENCES market_snapshots (market_snapshot_id) ON DELETE RESTRICT, 
	FOREIGN KEY(quote_id) REFERENCES market_quotes (quote_id) ON DELETE RESTRICT
);

-- table operator_market_prior_baseline_revisions
CREATE TABLE operator_market_prior_baseline_revisions (
	market_prior_baseline_revision_id TEXT NOT NULL, 
	market_prior_baseline_family_id TEXT NOT NULL, 
	revision_no INTEGER NOT NULL, 
	supersedes_revision_id TEXT, 
	task_family_id TEXT NOT NULL, 
	work_item_id TEXT NOT NULL, 
	task_snapshot_hash TEXT NOT NULL, 
	slate_revision_id TEXT NOT NULL, 
