	action_id TEXT NOT NULL, 
	created_at TEXT NOT NULL, 
	PRIMARY KEY (market_prior_baseline_revision_id), 
	CONSTRAINT ck_market_prior_baseline_revision CHECK (revision_no >= 1), 
