	CONSTRAINT uq_judgment_factor_offset_index UNIQUE (operator_match_judgment_factor_adjustment_id, face_index), 
	CONSTRAINT uq_judgment_factor_offset_face UNIQUE (operator_match_judgment_factor_adjustment_id, face_code), 
