	CONSTRAINT ck_judgment_belief_probability_canonical CHECK (typeof(belief_probability_decimal) = 'text' AND printf('%.12f', CAST(belief_probability_decimal AS REAL)) = belief_probability_decimal AND CAST(belief_probability_decimal AS REAL) BETWEEN 0.0 AND 1.0), 
	CONSTRAINT ck_judgment_delta_probability_canonical CHECK (typeof(delta_probability_decimal) = 'text' AND printf('%.12f', CAST(delta_probability_decimal AS REAL)) = delta_probability_decimal AND CAST(delta_probability_decimal AS REAL) BETWEEN -1.0 AND 1.0), 
	CONSTRAINT uq_judgment_probability_index UNIQUE (operator_match_judgment_revision_id, face_index), 
	CONSTRAINT uq_judgment_probability_face UNIQUE (operator_match_judgment_revision_id, face_code), 
	FOREIGN KEY(operator_match_judgment_revision_id) REFERENCES operator_match_judgment_revisions (operator_match_judgment_revision_id) ON DELETE RESTRICT
