	received_at TEXT NOT NULL, 
	PRIMARY KEY (no_ticket_command_receipt_id), 
	CONSTRAINT ck_operator_no_ticket_command_kind CHECK (command_kind IN ('record_no_ticket', 'supersede_no_ticket')), 
	CONSTRAINT ck_operator_no_ticket_command_result CHECK (result IN ('recorded', 'task_snapshot_changed', 'already_current')), 
	CONSTRAINT ck_operator_no_ticket_command_revision_result CHECK ((result IN ('recorded', 'already_current') AND no_ticket_revision_id IS NOT NULL) OR (result = 'task_snapshot_changed' AND no_ticket_revision_id IS NULL)), 
	UNIQUE (action_id), 
	FOREIGN KEY(action_id) REFERENCES actions (action_id) ON DELETE RESTRICT, 
	FOREIGN KEY(no_ticket_revision_id) REFERENCES operator_no_ticket_revisions (no_ticket_revision_id) ON DELETE RESTRICT
);

-- table operator_no_ticket_offer_scopes
CREATE TABLE operator_no_ticket_offer_scopes (
	no_ticket_offer_scope_id TEXT NOT NULL, 
	no_ticket_revision_id TEXT NOT NULL, 
	scope_index INTEGER NOT NULL, 
	official_offer_revision_id TEXT NOT NULL, 
	effective_cutoff_at TEXT NOT NULL, 
	PRIMARY KEY (no_ticket_offer_scope_id), 
	CONSTRAINT ck_operator_no_ticket_offer_scope_index CHECK (scope_index >= 0), 
	CONSTRAINT uq_operator_no_ticket_offer_scope_index UNIQUE (no_ticket_revision_id, scope_index), 
	CONSTRAINT uq_operator_no_ticket_offer_scope_offer UNIQUE (no_ticket_revision_id, official_offer_revision_id), 
	FOREIGN KEY(no_ticket_revision_id) REFERENCES operator_no_ticket_revisions (no_ticket_revision_id) ON DELETE RESTRICT, 
	FOREIGN KEY(official_offer_revision_id) REFERENCES official_offer_revisions (official_offer_revision_id) ON DELETE RESTRICT
);

-- table operator_no_ticket_revisions
CREATE TABLE operator_no_ticket_revisions (
	no_ticket_revision_id TEXT NOT NULL, 
	no_ticket_family_id TEXT NOT NULL, 
	revision_no INTEGER NOT NULL, 
	supersedes_revision_id TEXT, 
	action_id TEXT NOT NULL, 
	task_family_id TEXT NOT NULL, 
	work_item_id TEXT NOT NULL, 
	task_snapshot_hash TEXT NOT NULL, 
	slate_revision_id TEXT NOT NULL, 
	reason_code TEXT NOT NULL, 
	reason_basis TEXT NOT NULL, 
	reason_text TEXT NOT NULL, 
	rule_ids_json TEXT NOT NULL, 
	phase TEXT NOT NULL, 
	requirement_snapshot_hash TEXT, 
	missing_requirement_ids_json TEXT NOT NULL, 
	stale_requirement_ids_json TEXT NOT NULL, 
	conflicting_requirement_ids_json TEXT NOT NULL, 
	market_prior_baseline_revision_id TEXT, 
	baseline_envelope_revision_id TEXT, 
	candidate_set_revision_id TEXT, 
	comparison_candidate_revision_id TEXT, 
	deployment_outcome TEXT NOT NULL, 
	content_hash TEXT NOT NULL, 
	recorded_at TEXT NOT NULL, 
	PRIMARY KEY (no_ticket_revision_id), 
	CONSTRAINT ck_operator_no_ticket_revision_positive CHECK (revision_no >= 1), 
	CONSTRAINT ck_operator_no_ticket_reason_code CHECK (reason_code IN ('human_all_dice', 'evidence_incomplete', 'no_compliant_structure_within_cap', 'discipline_brake', 'operator_discretion')), 
	CONSTRAINT ck_operator_no_ticket_reason_basis CHECK (reason_basis IN ('rule_derived', 'operator_judgment')), 
	CONSTRAINT ck_operator_no_ticket_reason_text CHECK (length(trim(reason_text)) > 0), 
	CONSTRAINT ck_operator_no_ticket_phase CHECK (phase IN ('discovery', 'evidence', 'baseline', 'envelope', 'candidate', 'artifact')), 
	CONSTRAINT ck_operator_no_ticket_deployment_outcome CHECK (deployment_outcome IN ('no_ticket', 'partially_placed', 'reopened')), 
	CONSTRAINT uq_operator_no_ticket_family_revision UNIQUE (no_ticket_family_id, revision_no), 
	UNIQUE (supersedes_revision_id), 
	FOREIGN KEY(supersedes_revision_id) REFERENCES operator_no_ticket_revisions (no_ticket_revision_id) ON DELETE RESTRICT, 
	UNIQUE (action_id), 
	FOREIGN KEY(action_id) REFERENCES actions (action_id) ON DELETE RESTRICT, 
	FOREIGN KEY(slate_revision_id) REFERENCES official_sale_slate_revisions (slate_revision_id) ON DELETE RESTRICT, 
	FOREIGN KEY(market_prior_baseline_revision_id) REFERENCES operator_market_prior_baseline_revisions (market_prior_baseline_revision_id) ON DELETE RESTRICT, 
	FOREIGN KEY(baseline_envelope_revision_id) REFERENCES operator_baseline_envelope_revisions (baseline_envelope_revision_id) ON DELETE RESTRICT, 
	FOREIGN KEY(candidate_set_revision_id) REFERENCES operator_candidate_set_revisions (candidate_set_revision_id) ON DELETE RESTRICT, 
	FOREIGN KEY(comparison_candidate_revision_id) REFERENCES operator_candidates (candidate_revision_id) ON DELETE RESTRICT
);

-- table operator_outcome_revisions
CREATE TABLE operator_outcome_revisions (
	outcome_revision_id TEXT NOT NULL, 
	outcome_family_id TEXT NOT NULL, 
	revision_no INTEGER NOT NULL, 
	supersedes_revision_id TEXT, 
	outcome_index INTEGER NOT NULL, 
	match_id TEXT NOT NULL, 
	match_result_revision_id TEXT NOT NULL, 
	result_set_revision_id TEXT NOT NULL, 
	result_disposition TEXT NOT NULL, 
	home_90 INTEGER, 
	away_90 INTEGER, 
	source_artifact_retrieval_ids_json TEXT NOT NULL, 
	recorded_at TEXT NOT NULL, 
	action_id TEXT NOT NULL, 
	PRIMARY KEY (outcome_revision_id), 
	CONSTRAINT ck_outcome_revision CHECK (revision_no >= 1), 
	CONSTRAINT ck_outcome_index CHECK (outcome_index >= 0), 
	CONSTRAINT ck_outcome_shape CHECK ((result_disposition = 'played_90' AND home_90 >= 0 AND away_90 >= 0) OR (result_disposition = 'official_void' AND home_90 IS NULL AND away_90 IS NULL)), 
	CONSTRAINT uq_outcome_family_revision UNIQUE (outcome_family_id, revision_no), 
	CONSTRAINT uq_outcome_action_index UNIQUE (action_id, outcome_index), 
	UNIQUE (supersedes_revision_id), 
	FOREIGN KEY(supersedes_revision_id) REFERENCES operator_outcome_revisions (outcome_revision_id) ON DELETE RESTRICT, 
	FOREIGN KEY(match_id) REFERENCES matches (match_id) ON DELETE RESTRICT, 
	UNIQUE (match_result_revision_id), 
	FOREIGN KEY(match_result_revision_id) REFERENCES operator_result_match_revisions (match_result_revision_id) ON DELETE RESTRICT, 
	FOREIGN KEY(result_set_revision_id) REFERENCES operator_result_set_revisions (result_set_revision_id) ON DELETE RESTRICT, 
	FOREIGN KEY(action_id) REFERENCES actions (action_id) ON DELETE RESTRICT
);

-- table operator_placement_cash_links
CREATE TABLE operator_placement_cash_links (
	placement_cash_link_id TEXT NOT NULL, 
	ticket_id TEXT NOT NULL, 
	transaction_id TEXT NOT NULL, 
	stake_minor INTEGER NOT NULL, 
	currency TEXT NOT NULL, 
	action_id TEXT NOT NULL, 
	created_at TEXT NOT NULL, 
	PRIMARY KEY (placement_cash_link_id), 
	CONSTRAINT ck_operator_placement_cash_stake CHECK (stake_minor > 0), 
	CONSTRAINT ck_operator_placement_cash_currency CHECK (length(currency) = 3), 
	UNIQUE (ticket_id), 
	FOREIGN KEY(ticket_id) REFERENCES tickets (ticket_id) ON DELETE RESTRICT, 
	UNIQUE (transaction_id), 
	FOREIGN KEY(transaction_id) REFERENCES cash_transactions (transaction_id) ON DELETE RESTRICT, 
	UNIQUE (action_id), 
	FOREIGN KEY(action_id) REFERENCES actions (action_id) ON DELETE RESTRICT
);

-- table operator_projection_cursors
CREATE TABLE operator_projection_cursors (
	consumer_name TEXT NOT NULL, 
	last_sequence INTEGER NOT NULL, 
	updated_at TEXT NOT NULL, 
	PRIMARY KEY (consumer_name), 
	CONSTRAINT ck_operator_projection_cursors_sequence CHECK (last_sequence >= 0)
);

-- table operator_protected_artifact_bindings
CREATE TABLE operator_protected_artifact_bindings (
	protected_artifact_binding_id TEXT NOT NULL, 
	ticket_artifact_id TEXT NOT NULL, 
	lineage_revision_id TEXT NOT NULL, 
	candidate_revision_id TEXT NOT NULL, 
	candidate_ticket_id TEXT NOT NULL, 
	ticket_index INTEGER NOT NULL, 
	ticket_kind TEXT NOT NULL, 
	stake_minor INTEGER NOT NULL, 
	currency TEXT NOT NULL, 
	composition_hash TEXT NOT NULL, 
	fixed_prize_policy_revision_id TEXT, 
	frozen_deadline_at TEXT NOT NULL, 
	action_id TEXT NOT NULL, 
	created_at TEXT NOT NULL, 
	PRIMARY KEY (protected_artifact_binding_id), 
	CONSTRAINT ck_operator_protected_artifact_ticket_index CHECK (ticket_index >= 0), 
	CONSTRAINT ck_operator_protected_artifact_ticket_kind CHECK (ticket_kind IN ('jczq_pass', 'sfc', 'renjiu')), 
	CONSTRAINT ck_operator_protected_artifact_stake_minor CHECK (stake_minor > 0), 
	CONSTRAINT ck_operator_protected_artifact_currency CHECK (length(currency) = 3), 
	CONSTRAINT ck_operator_protected_artifact_policy CHECK ((ticket_kind = 'jczq_pass' AND fixed_prize_policy_revision_id IS NULL) OR (ticket_kind IN ('sfc', 'renjiu') AND fixed_prize_policy_revision_id IS NOT NULL)), 
	CONSTRAINT uq_operator_protected_artifact_candidate_ticket_index UNIQUE (candidate_revision_id, ticket_index), 
	UNIQUE (ticket_artifact_id), 
	FOREIGN KEY(ticket_artifact_id) REFERENCES audited_ticket_artifacts (ticket_artifact_id) ON DELETE RESTRICT, 
	FOREIGN KEY(lineage_revision_id) REFERENCES operator_ticket_decision_lineage_revisions (lineage_revision_id) ON DELETE RESTRICT, 
	FOREIGN KEY(candidate_revision_id) REFERENCES operator_candidates (candidate_revision_id) ON DELETE RESTRICT, 
	FOREIGN KEY(candidate_ticket_id) REFERENCES operator_candidate_tickets (candidate_ticket_id) ON DELETE RESTRICT, 
	FOREIGN KEY(fixed_prize_policy_revision_id) REFERENCES zucai_fixed_prize_policy_revisions (fixed_prize_policy_revision_id) ON DELETE RESTRICT, 
	FOREIGN KEY(action_id) REFERENCES actions (action_id) ON DELETE RESTRICT
);

-- table operator_protected_artifact_offer_revision_links
CREATE TABLE operator_protected_artifact_offer_revision_links (
	protected_artifact_offer_revision_link_id TEXT NOT NULL, 
	ticket_artifact_id TEXT NOT NULL, 
	offer_index INTEGER NOT NULL, 
	official_offer_revision_id TEXT NOT NULL, 
	PRIMARY KEY (protected_artifact_offer_revision_link_id), 
	CONSTRAINT ck_operator_protected_artifact_offer_index CHECK (offer_index >= 0), 
	CONSTRAINT uq_operator_protected_artifact_offer_index UNIQUE (ticket_artifact_id, offer_index), 
	CONSTRAINT uq_operator_protected_artifact_offer_revision UNIQUE (ticket_artifact_id, official_offer_revision_id), 
	FOREIGN KEY(ticket_artifact_id) REFERENCES operator_protected_artifact_bindings (ticket_artifact_id) ON DELETE RESTRICT, 
	FOREIGN KEY(official_offer_revision_id) REFERENCES official_offer_revisions (official_offer_revision_id) ON DELETE RESTRICT
);

-- table operator_result_match_revisions
CREATE TABLE operator_result_match_revisions (
	match_result_revision_id TEXT NOT NULL, 
	result_set_revision_id TEXT NOT NULL, 
	match_index INTEGER NOT NULL, 
	official_match_no TEXT NOT NULL, 
	official_offer_revision_id TEXT NOT NULL, 
	match_id TEXT NOT NULL, 
	normalized_disposition TEXT, 
	normalized_home_90 INTEGER, 
	normalized_away_90 INTEGER, 
	agreement_state TEXT NOT NULL, 
	PRIMARY KEY (match_result_revision_id), 
	CONSTRAINT ck_result_match_index CHECK (match_index >= 0), 
	CONSTRAINT ck_result_match_agreement CHECK (agreement_state IN ('missing', 'conflict', 'agreed')), 
	CONSTRAINT ck_result_match_normalized_shape CHECK ((agreement_state IN ('missing', 'conflict') AND normalized_disposition IS NULL AND normalized_home_90 IS NULL AND normalized_away_90 IS NULL) OR (agreement_state = 'agreed' AND normalized_disposition = 'played_90' AND normalized_home_90 >= 0 AND normalized_away_90 >= 0) OR (agreement_state = 'agreed' AND normalized_disposition IN ('postponed', 'official_void') AND normalized_home_90 IS NULL AND normalized_away_90 IS NULL)), 
	CONSTRAINT uq_result_match_index UNIQUE (result_set_revision_id, match_index), 
	CONSTRAINT uq_result_match_offer UNIQUE (result_set_revision_id, official_offer_revision_id), 
	CONSTRAINT uq_result_match_identity UNIQUE (result_set_revision_id, match_id), 
	FOREIGN KEY(result_set_revision_id) REFERENCES operator_result_set_revisions (result_set_revision_id) ON DELETE RESTRICT, 
	FOREIGN KEY(official_offer_revision_id) REFERENCES official_offer_revisions (official_offer_revision_id) ON DELETE RESTRICT, 
	FOREIGN KEY(match_id) REFERENCES matches (match_id) ON DELETE RESTRICT
);

-- table operator_result_set_families
CREATE TABLE operator_result_set_families (
	result_set_family_id TEXT NOT NULL, 
	task_family_id TEXT NOT NULL, 
	lane TEXT NOT NULL, 
	business_key TEXT NOT NULL, 
	created_at TEXT NOT NULL, 
	PRIMARY KEY (result_set_family_id), 
	CONSTRAINT ck_result_family_lane CHECK (lane IN ('jczq', 'zucai')), 
	CONSTRAINT uq_result_family_business_key UNIQUE (lane, business_key)
);

-- table operator_result_set_revisions
CREATE TABLE operator_result_set_revisions (
	result_set_revision_id TEXT NOT NULL, 
	result_set_family_id TEXT NOT NULL, 
	revision_no INTEGER NOT NULL, 
	supersedes_revision_id TEXT, 
	task_family_id TEXT NOT NULL, 
	work_item_id TEXT NOT NULL, 
	lane TEXT NOT NULL, 
	business_key TEXT NOT NULL, 
	task_snapshot_hash TEXT NOT NULL, 
	slate_revision_id TEXT NOT NULL, 
	result_cutoff_at TEXT NOT NULL, 
	importer_version TEXT NOT NULL, 
	zucai_prize_table_revision_id TEXT, 
	match_count INTEGER NOT NULL, 
	source_receipt_count INTEGER NOT NULL, 
	outcome_count INTEGER NOT NULL, 
	content_hash TEXT NOT NULL, 
	action_id TEXT NOT NULL, 
	created_at TEXT NOT NULL, 
	PRIMARY KEY (result_set_revision_id), 
	CONSTRAINT ck_result_set_revision CHECK (revision_no >= 1), 
	CONSTRAINT ck_result_set_lane CHECK (lane IN ('jczq', 'zucai')), 
	CONSTRAINT ck_result_set_match_count CHECK (match_count >= 1), 
	CONSTRAINT ck_result_set_source_count CHECK (source_receipt_count = match_count * 3), 
	CONSTRAINT ck_result_set_outcome_count CHECK (outcome_count BETWEEN 0 AND match_count), 
	CONSTRAINT ck_result_set_prize_lane CHECK ((lane = 'jczq' AND zucai_prize_table_revision_id IS NULL) OR lane = 'zucai'), 
	CONSTRAINT uq_result_set_family_revision UNIQUE (result_set_family_id, revision_no), 
	FOREIGN KEY(result_set_family_id) REFERENCES operator_result_set_families (result_set_family_id) ON DELETE RESTRICT, 
	UNIQUE (supersedes_revision_id), 
	FOREIGN KEY(supersedes_revision_id) REFERENCES operator_result_set_revisions (result_set_revision_id) ON DELETE RESTRICT, 
	FOREIGN KEY(slate_revision_id) REFERENCES official_sale_slate_revisions (slate_revision_id) ON DELETE RESTRICT, 
	FOREIGN KEY(zucai_prize_table_revision_id) REFERENCES zucai_prize_table_revisions (prize_table_revision_id) ON DELETE RESTRICT, 
	UNIQUE (action_id), 
	FOREIGN KEY(action_id) REFERENCES actions (action_id) ON DELETE RESTRICT
);

-- table operator_result_source_receipts
CREATE TABLE operator_result_source_receipts (
	result_source_receipt_id TEXT NOT NULL, 
	match_result_revision_id TEXT NOT NULL, 
	source_index INTEGER NOT NULL, 
	source_kind TEXT NOT NULL, 
	source_artifact_retrieval_id TEXT, 
	captured_at TEXT, 
	source_disposition TEXT, 
	home_90 INTEGER, 
	away_90 INTEGER, 
	receipt_state TEXT NOT NULL, 
	invalid_code TEXT, 
	PRIMARY KEY (result_source_receipt_id), 
	CONSTRAINT ck_result_source_index CHECK (source_index BETWEEN 0 AND 2), 
	CONSTRAINT ck_result_source_kind CHECK (source_kind IN ('api_football', 'sporttery_game90', 'okooo_manual')), 
	CONSTRAINT ck_result_source_state CHECK (receipt_state IN ('missing', 'invalid', 'available')), 
	CONSTRAINT ck_result_source_invalid_code CHECK (invalid_code IS NULL OR invalid_code IN ('artifact_unreadable', 'schema_mismatch', 'invalid_score', 'source_identity_mismatch', 'unsupported_status')), 
	CONSTRAINT ck_result_source_shape CHECK ((receipt_state = 'missing' AND source_artifact_retrieval_id IS NULL AND captured_at IS NULL AND source_disposition IS NULL AND home_90 IS NULL AND away_90 IS NULL AND invalid_code IS NULL) OR (receipt_state = 'invalid' AND source_artifact_retrieval_id IS NOT NULL AND captured_at IS NOT NULL AND source_disposition IS NULL AND home_90 IS NULL AND away_90 IS NULL AND invalid_code IS NOT NULL) OR (receipt_state = 'available' AND source_artifact_retrieval_id IS NOT NULL AND captured_at IS NOT NULL AND invalid_code IS NULL AND ((source_disposition = 'played_90' AND home_90 >= 0 AND away_90 >= 0) OR (source_disposition IN ('postponed', 'official_void') AND home_90 IS NULL AND away_90 IS NULL)))), 
	CONSTRAINT uq_result_source_index UNIQUE (match_result_revision_id, source_index), 
	CONSTRAINT uq_result_source_kind UNIQUE (match_result_revision_id, source_kind), 
	FOREIGN KEY(match_result_revision_id) REFERENCES operator_result_match_revisions (match_result_revision_id) ON DELETE RESTRICT, 
	FOREIGN KEY(source_artifact_retrieval_id) REFERENCES artifact_retrievals (artifact_retrieval_id) ON DELETE RESTRICT
);

-- table operator_review_eligibility_facts
CREATE TABLE operator_review_eligibility_facts (
	review_eligibility_fact_id TEXT NOT NULL, 
	action_id TEXT NOT NULL, 
	fact_index INTEGER NOT NULL, 
	terminal_trigger TEXT NOT NULL, 
	task_family_id TEXT NOT NULL, 
	work_item_id TEXT NOT NULL, 
	task_snapshot_hash TEXT NOT NULL, 
	no_ticket_revision_id TEXT, 
	artifact_terminal_receipt_id TEXT, 
	settlement_run_id TEXT, 
	market_prior_baseline_revision_id TEXT, 
	review_kind TEXT NOT NULL, 
	readiness_condition TEXT NOT NULL, 
	content_hash TEXT NOT NULL, 
	created_at TEXT NOT NULL, 
	PRIMARY KEY (review_eligibility_fact_id), 
	CONSTRAINT ck_operator_review_eligibility_fact_index CHECK (fact_index >= 0), 
	CONSTRAINT ck_operator_review_eligibility_terminal_trigger CHECK (terminal_trigger IN ('no_ticket', 'artifact_terminal', 'official_cancellation', 'settlement')), 
	CONSTRAINT ck_operator_review_eligibility_source CHECK ((terminal_trigger = 'no_ticket' AND no_ticket_revision_id IS NOT NULL AND artifact_terminal_receipt_id IS NULL AND settlement_run_id IS NULL) OR (terminal_trigger IN ('artifact_terminal', 'official_cancellation') AND no_ticket_revision_id IS NULL AND artifact_terminal_receipt_id IS NOT NULL AND settlement_run_id IS NULL) OR (terminal_trigger = 'settlement' AND no_ticket_revision_id IS NULL AND artifact_terminal_receipt_id IS NULL AND settlement_run_id IS NOT NULL)), 
	CONSTRAINT ck_operator_review_eligibility_review_kind CHECK (review_kind IN ('operational_data_availability', 'forecast_truth')), 
	CONSTRAINT ck_operator_review_eligibility_readiness CHECK (readiness_condition IN ('immediate', 'outcomes_required')), 
	CONSTRAINT ck_operator_review_eligibility_kind_readiness CHECK ((review_kind = 'operational_data_availability' AND readiness_condition = 'immediate' AND market_prior_baseline_revision_id IS NULL) OR (review_kind = 'forecast_truth' AND readiness_condition = 'outcomes_required' AND market_prior_baseline_revision_id IS NOT NULL)), 
	CONSTRAINT uq_operator_review_eligibility_action_index UNIQUE (action_id, fact_index), 
	CONSTRAINT uq_operator_review_eligibility_settlement_run UNIQUE (settlement_run_id), 
	FOREIGN KEY(action_id) REFERENCES actions (action_id) ON DELETE RESTRICT, 
	FOREIGN KEY(no_ticket_revision_id) REFERENCES operator_no_ticket_revisions (no_ticket_revision_id) ON DELETE RESTRICT, 
	FOREIGN KEY(artifact_terminal_receipt_id) REFERENCES operator_artifact_terminal_receipts (artifact_terminal_receipt_id) ON DELETE RESTRICT, 
	FOREIGN KEY(settlement_run_id) REFERENCES operator_task_settlement_runs (settlement_run_id) ON DELETE RESTRICT, 
	FOREIGN KEY(market_prior_baseline_revision_id) REFERENCES operator_market_prior_baseline_revisions (market_prior_baseline_revision_id) ON DELETE RESTRICT
);

-- table operator_review_items
CREATE TABLE operator_review_items (
	review_id TEXT NOT NULL, 
	review_eligibility_fact_id TEXT NOT NULL, 
	task_family_id TEXT NOT NULL, 
	work_item_id TEXT NOT NULL, 
	task_snapshot_hash TEXT NOT NULL, 
	lane TEXT NOT NULL, 
	business_key TEXT NOT NULL, 
	review_kind TEXT NOT NULL, 
	market_prior_baseline_revision_id TEXT, 
	outcome_revision_ids_json TEXT NOT NULL, 
	materialized_by_action_id TEXT NOT NULL, 
	materialized_at TEXT NOT NULL, 
	PRIMARY KEY (review_id), 
	CONSTRAINT ck_operator_review_lane CHECK (lane IN ('jczq', 'zucai')), 
	CONSTRAINT ck_operator_review_kind CHECK (review_kind IN ('operational_data_availability', 'forecast_truth')), 
	CONSTRAINT ck_operator_review_outcomes_json CHECK (json_valid(outcome_revision_ids_json) AND json_type(outcome_revision_ids_json) = 'array'), 
	CONSTRAINT ck_operator_review_readiness_shape CHECK ((review_kind = 'operational_data_availability' AND market_prior_baseline_revision_id IS NULL AND json_array_length(outcome_revision_ids_json) = 0) OR (review_kind = 'forecast_truth' AND market_prior_baseline_revision_id IS NOT NULL AND json_array_length(outcome_revision_ids_json) > 0)), 
	UNIQUE (review_eligibility_fact_id), 
	FOREIGN KEY(review_eligibility_fact_id) REFERENCES operator_review_eligibility_facts (review_eligibility_fact_id) ON DELETE RESTRICT, 
	FOREIGN KEY(market_prior_baseline_revision_id) REFERENCES operator_market_prior_baseline_revisions (market_prior_baseline_revision_id) ON DELETE RESTRICT, 
	UNIQUE (materialized_by_action_id), 
	FOREIGN KEY(materialized_by_action_id) REFERENCES actions (action_id) ON DELETE RESTRICT
);

-- table operator_scoreboard_effect_disposition_revisions
CREATE TABLE operator_scoreboard_effect_disposition_revisions (
	disposition_revision_id TEXT NOT NULL, 
	family_id TEXT NOT NULL, 
	revision_no INTEGER NOT NULL, 
	supersedes_revision_id TEXT, 
	review_id TEXT NOT NULL, 
	disposition TEXT NOT NULL, 
	reason TEXT NOT NULL, 
	pre_update_legacy_sha256 TEXT NOT NULL, 
	required_metric_keys_json TEXT NOT NULL, 
	created_by_action_id TEXT NOT NULL, 
	created_at TEXT NOT NULL, 
	PRIMARY KEY (disposition_revision_id), 
	CONSTRAINT ck_scoreboard_disposition_revision CHECK (revision_no >= 1), 
	CONSTRAINT ck_scoreboard_disposition_kind CHECK (disposition IN ('effect_required', 'no_effect')), 
	CONSTRAINT ck_scoreboard_disposition_reason CHECK (length(trim(reason)) > 0), 
	CONSTRAINT ck_scoreboard_disposition_pre_hash CHECK (length(pre_update_legacy_sha256) = 64), 
	CONSTRAINT ck_scoreboard_disposition_metrics_json CHECK (json_valid(required_metric_keys_json) AND json_type(required_metric_keys_json) = 'array'), 
	CONSTRAINT ck_scoreboard_disposition_metric_shape CHECK ((disposition = 'effect_required' AND json_array_length(required_metric_keys_json) > 0) OR (disposition = 'no_effect' AND json_array_length(required_metric_keys_json) = 0)), 
	CONSTRAINT uq_scoreboard_disposition_family_revision UNIQUE (family_id, revision_no), 
	CONSTRAINT uq_scoreboard_disposition_review_revision UNIQUE (review_id, revision_no), 
	UNIQUE (supersedes_revision_id), 
	FOREIGN KEY(supersedes_revision_id) REFERENCES operator_scoreboard_effect_disposition_revisions (disposition_revision_id) ON DELETE RESTRICT, 
	FOREIGN KEY(review_id) REFERENCES operator_review_items (review_id) ON DELETE RESTRICT, 
	UNIQUE (created_by_action_id), 
	FOREIGN KEY(created_by_action_id) REFERENCES actions (action_id) ON DELETE RESTRICT
);

-- table operator_scoreboard_review_completion_receipts
CREATE TABLE operator_scoreboard_review_completion_receipts (
	completion_receipt_id TEXT NOT NULL, 
	review_id TEXT NOT NULL, 
	disposition_revision_id TEXT NOT NULL, 
	completion_request_id TEXT, 
	post_update_legacy_sha256 TEXT, 
	observation_action_ids_json TEXT, 
	shadow_review_id TEXT, 
	shadow_source_high_watermark INTEGER, 
	completed_by_action_id TEXT NOT NULL, 
	completed_at TEXT NOT NULL, 
	PRIMARY KEY (completion_receipt_id), 
	CONSTRAINT ck_review_completion_receipt_shape CHECK ((completion_request_id IS NULL AND post_update_legacy_sha256 IS NULL AND observation_action_ids_json IS NULL AND shadow_review_id IS NULL AND shadow_source_high_watermark IS NULL) OR (completion_request_id IS NOT NULL AND length(post_update_legacy_sha256) = 64 AND json_valid(observation_action_ids_json) AND json_type(observation_action_ids_json) = 'array' AND json_array_length(observation_action_ids_json) > 0 AND shadow_review_id IS NOT NULL AND shadow_source_high_watermark >= 0)), 
	UNIQUE (review_id), 
	FOREIGN KEY(review_id) REFERENCES operator_review_items (review_id) ON DELETE RESTRICT, 
	UNIQUE (disposition_revision_id), 
	FOREIGN KEY(disposition_revision_id) REFERENCES operator_scoreboard_effect_disposition_revisions (disposition_revision_id) ON DELETE RESTRICT, 
	UNIQUE (completion_request_id), 
	FOREIGN KEY(completion_request_id) REFERENCES operator_scoreboard_review_completion_requests (completion_request_id) ON DELETE RESTRICT, 
	FOREIGN KEY(shadow_review_id) REFERENCES scoreboard_shadow_reviews (scoreboard_shadow_review_id) ON DELETE RESTRICT, 
	UNIQUE (completed_by_action_id), 
	FOREIGN KEY(completed_by_action_id) REFERENCES actions (action_id) ON DELETE RESTRICT
);

-- table operator_scoreboard_review_completion_requests
CREATE TABLE operator_scoreboard_review_completion_requests (
	completion_request_id TEXT NOT NULL, 
	action_id TEXT NOT NULL, 
	review_id TEXT NOT NULL, 
	disposition_revision_id TEXT NOT NULL, 
	shadow_review_token TEXT NOT NULL, 
	shadow_review_id TEXT NOT NULL, 
	shadow_source_high_watermark INTEGER NOT NULL, 
	compared_legacy_sha256 TEXT NOT NULL, 
	metric_keys_json TEXT NOT NULL, 
	observation_action_ids_json TEXT NOT NULL, 
	requested_at TEXT NOT NULL, 
	PRIMARY KEY (completion_request_id), 
	CONSTRAINT ck_review_completion_request_token CHECK (length(trim(shadow_review_token)) > 0), 
	CONSTRAINT ck_review_completion_request_watermark CHECK (shadow_source_high_watermark >= 0), 
	CONSTRAINT ck_review_completion_request_hash CHECK (length(compared_legacy_sha256) = 64), 
	CONSTRAINT ck_review_completion_request_metrics CHECK (json_valid(metric_keys_json) AND json_type(metric_keys_json) = 'array' AND json_array_length(metric_keys_json) > 0), 
	CONSTRAINT ck_review_completion_request_observations CHECK (json_valid(observation_action_ids_json) AND json_type(observation_action_ids_json) = 'array' AND json_array_length(observation_action_ids_json) > 0), 
	UNIQUE (action_id), 
	FOREIGN KEY(action_id) REFERENCES actions (action_id) ON DELETE RESTRICT, 
	FOREIGN KEY(review_id) REFERENCES operator_review_items (review_id) ON DELETE RESTRICT, 
	FOREIGN KEY(disposition_revision_id) REFERENCES operator_scoreboard_effect_disposition_revisions (disposition_revision_id) ON DELETE RESTRICT
);

-- table operator_scoreboard_review_observation_links
CREATE TABLE operator_scoreboard_review_observation_links (
	observation_link_id TEXT NOT NULL, 
	review_id TEXT NOT NULL, 
	disposition_revision_id TEXT NOT NULL, 
	metric_key TEXT NOT NULL, 
	scoreboard_observation_id TEXT NOT NULL, 
	observation_action_id TEXT NOT NULL, 
	observed_legacy_sha256 TEXT NOT NULL, 
	created_at TEXT NOT NULL, 
	PRIMARY KEY (observation_link_id), 
	CONSTRAINT ck_review_observation_metric CHECK (length(trim(metric_key)) > 0), 
	CONSTRAINT ck_review_observation_hash CHECK (length(observed_legacy_sha256) = 64), 
	CONSTRAINT uq_review_observation_disposition_metric UNIQUE (disposition_revision_id, metric_key), 
	FOREIGN KEY(review_id) REFERENCES operator_review_items (review_id) ON DELETE RESTRICT, 
	FOREIGN KEY(disposition_revision_id) REFERENCES operator_scoreboard_effect_disposition_revisions (disposition_revision_id) ON DELETE RESTRICT, 
	UNIQUE (scoreboard_observation_id), 
	FOREIGN KEY(scoreboard_observation_id) REFERENCES scoreboard_observations (scoreboard_observation_id) ON DELETE RESTRICT, 
	UNIQUE (observation_action_id), 
	FOREIGN KEY(observation_action_id) REFERENCES actions (action_id) ON DELETE RESTRICT
);

-- table operator_settlement_cash_links
CREATE TABLE operator_settlement_cash_links (
	settlement_cash_link_id TEXT NOT NULL, 
	settlement_revision_id TEXT NOT NULL, 
	transaction_id TEXT NOT NULL, 
	transaction_kind TEXT NOT NULL, 
	reverses_transaction_id TEXT, 
	amount_minor INTEGER NOT NULL, 
	currency TEXT NOT NULL, 
	PRIMARY KEY (settlement_cash_link_id), 
	CONSTRAINT ck_settlement_cash_kind CHECK (transaction_kind IN ('payout', 'payout_reversal')), 
	CONSTRAINT ck_settlement_cash_direction CHECK ((transaction_kind = 'payout' AND amount_minor > 0 AND reverses_transaction_id IS NULL) OR (transaction_kind = 'payout_reversal' AND amount_minor < 0 AND reverses_transaction_id IS NOT NULL)), 
	CONSTRAINT ck_settlement_cash_currency CHECK (length(currency) = 3), 
	FOREIGN KEY(settlement_revision_id) REFERENCES operator_ticket_settlement_revisions (settlement_revision_id) ON DELETE RESTRICT, 
	UNIQUE (transaction_id), 
	FOREIGN KEY(transaction_id) REFERENCES cash_transactions (transaction_id) ON DELETE RESTRICT, 
	UNIQUE (reverses_transaction_id), 
	FOREIGN KEY(reverses_transaction_id) REFERENCES cash_transactions (transaction_id) ON DELETE RESTRICT
);

-- table operator_settlement_requests
CREATE TABLE operator_settlement_requests (
	settlement_request_id TEXT NOT NULL, 
	action_id TEXT NOT NULL, 
	task_family_id TEXT NOT NULL, 
	work_item_id TEXT NOT NULL, 
	task_snapshot_hash TEXT NOT NULL, 
	slate_revision_id TEXT NOT NULL, 
	result_set_revision_id TEXT NOT NULL, 
	prize_table_revision_id TEXT, 
	requested_at TEXT NOT NULL, 
	PRIMARY KEY (settlement_request_id), 
	UNIQUE (action_id), 
	FOREIGN KEY(action_id) REFERENCES actions (action_id) ON DELETE RESTRICT, 
	FOREIGN KEY(slate_revision_id) REFERENCES official_sale_slate_revisions (slate_revision_id) ON DELETE RESTRICT, 
	FOREIGN KEY(result_set_revision_id) REFERENCES operator_result_set_revisions (result_set_revision_id) ON DELETE RESTRICT, 
	FOREIGN KEY(prize_table_revision_id) REFERENCES zucai_prize_table_revisions (prize_table_revision_id) ON DELETE RESTRICT
);

-- table operator_task_evidence_bundle_items
CREATE TABLE operator_task_evidence_bundle_items (
	task_evidence_bundle_item_id TEXT NOT NULL, 
	task_evidence_bundle_revision_id TEXT NOT NULL, 
	item_index INTEGER NOT NULL, 
	match_id TEXT NOT NULL, 
	evidence_bundle_id TEXT NOT NULL, 
	freeze_bundle_action_id TEXT NOT NULL, 
	requirement_states_json TEXT NOT NULL, 
	requirement_ref_tokens_json TEXT NOT NULL, 
	market_prior_ref_tokens_json TEXT NOT NULL, 
	conflicts_cleared_ref_tokens_json TEXT NOT NULL, 
	content_hash TEXT NOT NULL, 
	PRIMARY KEY (task_evidence_bundle_item_id), 
	CONSTRAINT ck_task_evidence_bundle_item_index CHECK (item_index >= 0), 
	CONSTRAINT uq_task_evidence_bundle_item_index UNIQUE (task_evidence_bundle_revision_id, item_index), 
	CONSTRAINT uq_task_evidence_bundle_match UNIQUE (task_evidence_bundle_revision_id, match_id), 
	FOREIGN KEY(task_evidence_bundle_revision_id) REFERENCES operator_task_evidence_bundle_revisions (task_evidence_bundle_revision_id) ON DELETE RESTRICT DEFERRABLE INITIALLY DEFERRED, 
	FOREIGN KEY(match_id) REFERENCES matches (match_id) ON DELETE RESTRICT, 
	FOREIGN KEY(evidence_bundle_id) REFERENCES evidence_bundles (evidence_bundle_id) ON DELETE RESTRICT, 
	FOREIGN KEY(freeze_bundle_action_id) REFERENCES actions (action_id) ON DELETE RESTRICT
);

-- table operator_task_evidence_bundle_revisions
CREATE TABLE operator_task_evidence_bundle_revisions (
	task_evidence_bundle_revision_id TEXT NOT NULL, 
	task_family_id TEXT NOT NULL, 
	lane TEXT NOT NULL, 
	business_key TEXT NOT NULL, 
	revision_no INTEGER NOT NULL, 
	evidence_freeze_request_id TEXT NOT NULL, 
	link_action_id TEXT NOT NULL, 
	slate_revision_id TEXT NOT NULL, 
	task_snapshot_hash TEXT NOT NULL, 
	requirement_revision_token TEXT NOT NULL, 
	information_cutoff_at TEXT NOT NULL, 
	policy_version TEXT NOT NULL, 
	dependency_fingerprint TEXT NOT NULL, 
	required_match_count INTEGER NOT NULL, 
	bundle_count INTEGER NOT NULL, 
	item_count INTEGER NOT NULL, 
	conflicts_cleared_count INTEGER NOT NULL, 
	content_hash TEXT NOT NULL, 
	frozen_at TEXT NOT NULL, 
	supersedes_revision_id TEXT, 
	PRIMARY KEY (task_evidence_bundle_revision_id), 
	CONSTRAINT ck_task_evidence_bundle_lane CHECK (lane IN ('jczq', 'zucai')), 
	CONSTRAINT ck_task_evidence_bundle_revision CHECK (revision_no >= 1), 
	CONSTRAINT ck_task_evidence_bundle_counts_reconciled CHECK (required_match_count >= 1 AND bundle_count = required_match_count AND item_count = bundle_count AND conflicts_cleared_count >= 0), 
	CONSTRAINT uq_task_evidence_bundle_revision UNIQUE (task_family_id, revision_no), 
	CONSTRAINT uq_task_evidence_bundle_content UNIQUE (task_family_id, content_hash), 
	UNIQUE (evidence_freeze_request_id), 
	FOREIGN KEY(evidence_freeze_request_id) REFERENCES operator_evidence_freeze_requests (evidence_freeze_request_id) ON DELETE RESTRICT, 
	UNIQUE (link_action_id), 
	FOREIGN KEY(link_action_id) REFERENCES actions (action_id) ON DELETE RESTRICT, 
	FOREIGN KEY(slate_revision_id) REFERENCES official_sale_slate_revisions (slate_revision_id) ON DELETE RESTRICT, 
	FOREIGN KEY(policy_version) REFERENCES policy_versions (policy_version_id) ON DELETE RESTRICT, 
	UNIQUE (supersedes_revision_id), 
	FOREIGN KEY(supersedes_revision_id) REFERENCES operator_task_evidence_bundle_revisions (task_evidence_bundle_revision_id) ON DELETE RESTRICT
);

-- table operator_task_settlement_runs
CREATE TABLE operator_task_settlement_runs (
	settlement_run_id TEXT NOT NULL, 
	settlement_request_id TEXT NOT NULL, 
	request_action_id TEXT NOT NULL, 
	settle_action_id TEXT NOT NULL, 
	task_family_id TEXT NOT NULL, 
	work_item_id TEXT NOT NULL, 
	work_item_snapshot_hash TEXT NOT NULL, 
	result_set_revision_id TEXT NOT NULL, 
	prize_table_revision_id TEXT, 
	settlement_method_version TEXT NOT NULL, 
	rounding_policy_version TEXT, 
	fixed_prize_policy_revision_ids_json TEXT NOT NULL, 
	settlement_state TEXT NOT NULL, 
	requested_ticket_count INTEGER NOT NULL, 
	eligible_ticket_count INTEGER NOT NULL, 
	settled_ticket_count INTEGER NOT NULL, 
	skipped_ticket_count INTEGER NOT NULL, 
	persisted_settlement_count INTEGER NOT NULL, 
	persisted_note_grade_count INTEGER NOT NULL, 
	persisted_leg_grade_count INTEGER NOT NULL, 
	persisted_cash_count INTEGER NOT NULL, 
	ticket_settlement_revision_ids_json TEXT NOT NULL, 
	completed_at TEXT NOT NULL, 
	PRIMARY KEY (settlement_run_id), 
	CONSTRAINT ck_task_settlement_state CHECK (settlement_state IN ('not_applicable', 'settled', 'corrected')), 
	CONSTRAINT ck_task_settlement_nonnegative_counts CHECK (requested_ticket_count >= 0 AND eligible_ticket_count >= 0 AND settled_ticket_count >= 0 AND skipped_ticket_count >= 0 AND persisted_settlement_count >= 0 AND persisted_note_grade_count >= 0 AND persisted_leg_grade_count >= 0 AND persisted_cash_count >= 0), 
	CONSTRAINT ck_task_settlement_reconciled_counts CHECK (requested_ticket_count = eligible_ticket_count + skipped_ticket_count AND eligible_ticket_count = settled_ticket_count AND settled_ticket_count = persisted_settlement_count), 
	CONSTRAINT ck_task_settlement_not_applicable CHECK (settlement_state != 'not_applicable' OR (requested_ticket_count = 0 AND persisted_note_grade_count = 0 AND persisted_leg_grade_count = 0 AND persisted_cash_count = 0)), 
	UNIQUE (settlement_request_id), 
	FOREIGN KEY(settlement_request_id) REFERENCES operator_settlement_requests (settlement_request_id) ON DELETE RESTRICT, 
	FOREIGN KEY(request_action_id) REFERENCES actions (action_id) ON DELETE RESTRICT, 
	UNIQUE (settle_action_id), 
	FOREIGN KEY(settle_action_id) REFERENCES actions (action_id) ON DELETE RESTRICT, 
	FOREIGN KEY(result_set_revision_id) REFERENCES operator_result_set_revisions (result_set_revision_id) ON DELETE RESTRICT, 
	FOREIGN KEY(prize_table_revision_id) REFERENCES zucai_prize_table_revisions (prize_table_revision_id) ON DELETE RESTRICT
);

-- table operator_task_settlement_skips
CREATE TABLE operator_task_settlement_skips (
	settlement_skip_id TEXT NOT NULL, 
	settlement_run_id TEXT NOT NULL, 
	skip_index INTEGER NOT NULL, 
	ticket_id TEXT NOT NULL, 
	reason_code TEXT NOT NULL, 
	PRIMARY KEY (settlement_skip_id), 
	CONSTRAINT ck_task_settlement_skip_index CHECK (skip_index >= 0), 
	CONSTRAINT ck_task_settlement_skip_reason CHECK (reason_code IN ('already_current', 'result_not_ready', 'prize_not_ready', 'placement_integrity_blocked')), 
	CONSTRAINT uq_task_settlement_skip_index UNIQUE (settlement_run_id, skip_index), 
	CONSTRAINT uq_task_settlement_skip_ticket UNIQUE (settlement_run_id, ticket_id), 
	FOREIGN KEY(settlement_run_id) REFERENCES operator_task_settlement_runs (settlement_run_id) ON DELETE RESTRICT, 
	FOREIGN KEY(ticket_id) REFERENCES tickets (ticket_id) ON DELETE RESTRICT
);

-- table operator_telegram_callback_attestations
