	CONSTRAINT ck_operator_telegram_owner_sequence CHECK (heartbeat_sequence >= 1), 
	CONSTRAINT uq_operator_telegram_owner_instance UNIQUE (account_id, owner_instance_id), 
	UNIQUE (registration_action_id), 
	FOREIGN KEY(registration_action_id) REFERENCES actions (action_id) ON DELETE RESTRICT
);

-- table operator_ticket_audit_override_receipts
CREATE TABLE operator_ticket_audit_override_receipts (
	ticket_audit_override_receipt_id TEXT NOT NULL, 
	action_id TEXT NOT NULL, 
	receipt_index INTEGER NOT NULL, 
