	reason TEXT NOT NULL, 
	rule_ids_json TEXT NOT NULL, 
	evidence_rejected_json TEXT NOT NULL, 
	recorded_at TEXT NOT NULL, 
	PRIMARY KEY (ticket_audit_override_receipt_id), 
	CONSTRAINT ck_operator_ticket_override_index CHECK (receipt_index >= 0), 
	CONSTRAINT ck_operator_ticket_override_reason CHECK (length(trim(reason)) > 0), 
	CONSTRAINT ck_operator_ticket_override_evidence_rejected CHECK (json_valid(evidence_rejected_json) AND json_array_length(evidence_rejected_json) >= 1), 
	CONSTRAINT uq_operator_ticket_override_action_index UNIQUE (action_id, receipt_index), 
	CONSTRAINT uq_operator_ticket_override_exact_finding UNIQUE (ticket_batch_revision_id, candidate_revision_id, candidate_audit_finding_id, audit_policy_version), 
	FOREIGN KEY(action_id) REFERENCES actions (action_id) ON DELETE RESTRICT, 
