	FOREIGN KEY(lineage_revision_id) REFERENCES operator_ticket_decision_lineage_revisions (lineage_revision_id) ON DELETE RESTRICT, 
	FOREIGN KEY(candidate_revision_id) REFERENCES operator_candidates (candidate_revision_id) ON DELETE RESTRICT, 
