-- table operator_ticket_note_leg_settlements
CREATE TABLE operator_ticket_note_leg_settlements (
	leg_settlement_id TEXT NOT NULL, 
	settlement_revision_id TEXT NOT NULL, 
	ticket_note_leg_id TEXT NOT NULL, 
	outcome_revision_id TEXT NOT NULL, 
	result_disposition TEXT NOT NULL, 
	market_result_code TEXT NOT NULL, 
	leg_grade TEXT NOT NULL, 
	PRIMARY KEY (leg_settlement_id), 
	CONSTRAINT ck_leg_settlement_disposition CHECK (result_disposition IN ('played_90', 'official_void')), 
	CONSTRAINT ck_leg_settlement_grade CHECK (leg_grade IN ('won', 'lost', 'void')), 
	CONSTRAINT uq_leg_settlement_leg UNIQUE (settlement_revision_id, ticket_note_leg_id), 
	FOREIGN KEY(settlement_revision_id) REFERENCES operator_ticket_settlement_revisions (settlement_revision_id) ON DELETE RESTRICT, 
	FOREIGN KEY(ticket_note_leg_id) REFERENCES operator_ticket_note_legs (ticket_note_leg_id) ON DELETE RESTRICT, 
	FOREIGN KEY(outcome_revision_id) REFERENCES operator_outcome_revisions (outcome_revision_id) ON DELETE RESTRICT
);

-- table operator_ticket_note_legs
CREATE TABLE operator_ticket_note_legs (
	ticket_note_leg_id TEXT NOT NULL, 
	ticket_note_id TEXT NOT NULL, 
	leg_index INTEGER NOT NULL, 
	official_offer_revision_id TEXT NOT NULL, 
	match_id TEXT NOT NULL, 
	market_definition_id TEXT NOT NULL, 
	selection_code TEXT NOT NULL, 
	quote_id TEXT, 
	booked_decimal_odds TEXT, 
	settlement_parameter_decimal TEXT, 
	fixed_prize_policy_revision_id TEXT, 
	action_id TEXT NOT NULL, 
	PRIMARY KEY (ticket_note_leg_id), 
	CONSTRAINT ck_operator_ticket_note_leg_index CHECK (leg_index >= 0), 
	CONSTRAINT ck_operator_ticket_note_leg_odds CHECK (booked_decimal_odds IS NULL OR typeof(booked_decimal_odds) = 'text' AND printf('%.12f', CAST(booked_decimal_odds AS REAL)) = booked_decimal_odds AND CAST(booked_decimal_odds AS REAL) > 0.0), 
	CONSTRAINT ck_operator_ticket_note_leg_parameter CHECK (settlement_parameter_decimal IS NULL OR typeof(settlement_parameter_decimal) = 'text' AND printf('%.12f', CAST(settlement_parameter_decimal AS REAL)) = settlement_parameter_decimal ), 
	CONSTRAINT ck_operator_ticket_note_leg_kind_shape CHECK ((fixed_prize_policy_revision_id IS NULL AND quote_id IS NOT NULL AND booked_decimal_odds IS NOT NULL) OR (fixed_prize_policy_revision_id IS NOT NULL AND quote_id IS NULL AND booked_decimal_odds IS NULL AND settlement_parameter_decimal IS NULL)), 
	CONSTRAINT uq_operator_ticket_note_leg_index UNIQUE (ticket_note_id, leg_index), 
	FOREIGN KEY(ticket_note_id) REFERENCES operator_ticket_notes (ticket_note_id) ON DELETE RESTRICT, 
	FOREIGN KEY(official_offer_revision_id) REFERENCES official_offer_revisions (official_offer_revision_id) ON DELETE RESTRICT, 
	FOREIGN KEY(match_id) REFERENCES matches (match_id) ON DELETE RESTRICT, 
	FOREIGN KEY(market_definition_id) REFERENCES market_definitions (market_definition_id) ON DELETE RESTRICT, 
	FOREIGN KEY(quote_id) REFERENCES market_quotes (quote_id) ON DELETE RESTRICT, 
	FOREIGN KEY(fixed_prize_policy_revision_id) REFERENCES zucai_fixed_prize_policy_revisions (fixed_prize_policy_revision_id) ON DELETE RESTRICT, 
	FOREIGN KEY(action_id) REFERENCES actions (action_id) ON DELETE RESTRICT
);

-- table operator_ticket_note_settlements
CREATE TABLE operator_ticket_note_settlements (
	note_settlement_id TEXT NOT NULL, 
	settlement_revision_id TEXT NOT NULL, 
	ticket_note_id TEXT NOT NULL, 
	note_grade TEXT NOT NULL, 
	unit_count INTEGER NOT NULL, 
	winning_unit_count INTEGER NOT NULL, 
	void_unit_count INTEGER NOT NULL, 
	correct_leg_count INTEGER NOT NULL, 
	void_leg_count INTEGER NOT NULL, 
	prize_tier_code TEXT, 
	payout_minor INTEGER NOT NULL, 
	PRIMARY KEY (note_settlement_id), 
	CONSTRAINT ck_note_settlement_grade CHECK (note_grade IN ('won', 'lost', 'void')), 
	CONSTRAINT ck_note_settlement_counts CHECK (unit_count > 0 AND winning_unit_count >= 0 AND void_unit_count >= 0 AND correct_leg_count >= 0 AND void_leg_count >= 0 AND payout_minor >= 0), 
	CONSTRAINT ck_note_settlement_grade_counts CHECK ((note_grade = 'won' AND winning_unit_count = unit_count AND void_unit_count = 0) OR (note_grade = 'void' AND winning_unit_count = 0 AND void_unit_count = unit_count AND prize_tier_code IS NULL) OR (note_grade = 'lost' AND winning_unit_count = 0 AND void_unit_count = 0 AND prize_tier_code IS NULL AND payout_minor = 0)), 
	CONSTRAINT uq_note_settlement_note UNIQUE (settlement_revision_id, ticket_note_id), 
	FOREIGN KEY(settlement_revision_id) REFERENCES operator_ticket_settlement_revisions (settlement_revision_id) ON DELETE RESTRICT, 
	FOREIGN KEY(ticket_note_id) REFERENCES operator_ticket_notes (ticket_note_id) ON DELETE RESTRICT
);

-- table operator_ticket_notes
CREATE TABLE operator_ticket_notes (
	ticket_note_id TEXT NOT NULL, 
	ticket_id TEXT NOT NULL, 
	ticket_artifact_id TEXT NOT NULL, 
	note_index INTEGER NOT NULL, 
	ticket_kind TEXT NOT NULL, 
	structure_code TEXT NOT NULL, 
	group_code TEXT, 
	currency TEXT NOT NULL, 
	unit_stake_minor INTEGER NOT NULL, 
	unit_count INTEGER NOT NULL, 
	stake_minor INTEGER NOT NULL, 
	composition_hash TEXT NOT NULL, 
	fixed_prize_policy_revision_id TEXT, 
	action_id TEXT NOT NULL, 
	created_at TEXT NOT NULL, 
	PRIMARY KEY (ticket_note_id), 
	CONSTRAINT ck_operator_ticket_note_index CHECK (note_index >= 0), 
	CONSTRAINT ck_operator_ticket_note_kind CHECK (ticket_kind IN ('jczq_pass', 'sfc', 'renjiu')), 
	CONSTRAINT ck_operator_ticket_note_currency CHECK (length(currency) = 3), 
	CONSTRAINT ck_operator_ticket_note_stake CHECK (unit_stake_minor > 0 AND unit_count > 0 AND stake_minor = unit_stake_minor * unit_count), 
	CONSTRAINT ck_operator_ticket_note_policy CHECK ((ticket_kind = 'jczq_pass' AND fixed_prize_policy_revision_id IS NULL) OR (ticket_kind IN ('sfc', 'renjiu') AND fixed_prize_policy_revision_id IS NOT NULL)), 
	CONSTRAINT uq_operator_ticket_note_index UNIQUE (ticket_id, note_index), 
	CONSTRAINT uq_operator_ticket_note_composition UNIQUE (ticket_id, composition_hash), 
	FOREIGN KEY(ticket_id) REFERENCES tickets (ticket_id) ON DELETE RESTRICT, 
	FOREIGN KEY(ticket_artifact_id) REFERENCES audited_ticket_artifacts (ticket_artifact_id) ON DELETE RESTRICT, 
	FOREIGN KEY(fixed_prize_policy_revision_id) REFERENCES zucai_fixed_prize_policy_revisions (fixed_prize_policy_revision_id) ON DELETE RESTRICT, 
	FOREIGN KEY(action_id) REFERENCES actions (action_id) ON DELETE RESTRICT
);

-- table operator_ticket_settlement_revisions
CREATE TABLE operator_ticket_settlement_revisions (
	settlement_revision_id TEXT NOT NULL, 
	settlement_family_id TEXT NOT NULL, 
	revision_no INTEGER NOT NULL, 
	supersedes_revision_id TEXT, 
	settlement_index INTEGER NOT NULL, 
	settlement_run_id TEXT NOT NULL, 
	ticket_id TEXT NOT NULL, 
	result_set_revision_id TEXT NOT NULL, 
	prize_table_revision_id TEXT, 
	fixed_prize_policy_revision_id TEXT, 
	method_version TEXT NOT NULL, 
	rounding_policy_version TEXT, 
	settlement_state TEXT NOT NULL, 
	currency TEXT NOT NULL, 
	stake_minor INTEGER NOT NULL, 
	distinct_note_count INTEGER NOT NULL, 
	paid_note_unit_count INTEGER NOT NULL, 
	winning_note_unit_count INTEGER NOT NULL, 
	void_note_unit_count INTEGER NOT NULL, 
	gross_payout_minor INTEGER NOT NULL, 
	action_id TEXT NOT NULL, 
	created_at TEXT NOT NULL, 
	PRIMARY KEY (settlement_revision_id), 
	CONSTRAINT ck_ticket_settlement_revision CHECK (revision_no >= 1), 
	CONSTRAINT ck_ticket_settlement_index CHECK (settlement_index >= 0), 
	CONSTRAINT ck_ticket_settlement_state CHECK (settlement_state IN ('settled', 'corrected')), 
	CONSTRAINT ck_ticket_settlement_currency CHECK (length(currency) = 3), 
	CONSTRAINT ck_ticket_settlement_stake CHECK (stake_minor > 0), 
	CONSTRAINT ck_ticket_settlement_counts CHECK (distinct_note_count > 0 AND paid_note_unit_count > 0 AND winning_note_unit_count >= 0 AND void_note_unit_count >= 0 AND winning_note_unit_count + void_note_unit_count <= paid_note_unit_count AND gross_payout_minor >= 0), 
	CONSTRAINT ck_ticket_settlement_lane_policy CHECK ((fixed_prize_policy_revision_id IS NULL AND prize_table_revision_id IS NULL AND rounding_policy_version IS NOT NULL) OR (fixed_prize_policy_revision_id IS NOT NULL AND prize_table_revision_id IS NOT NULL AND rounding_policy_version IS NULL AND void_note_unit_count = 0)), 
	CONSTRAINT uq_ticket_settlement_family_revision UNIQUE (settlement_family_id, revision_no), 
	CONSTRAINT uq_ticket_settlement_run_index UNIQUE (settlement_run_id, settlement_index), 
	UNIQUE (supersedes_revision_id), 
	FOREIGN KEY(supersedes_revision_id) REFERENCES operator_ticket_settlement_revisions (settlement_revision_id) ON DELETE RESTRICT, 
	FOREIGN KEY(settlement_run_id) REFERENCES operator_task_settlement_runs (settlement_run_id) ON DELETE RESTRICT, 
	FOREIGN KEY(ticket_id) REFERENCES tickets (ticket_id) ON DELETE RESTRICT, 
	FOREIGN KEY(result_set_revision_id) REFERENCES operator_result_set_revisions (result_set_revision_id) ON DELETE RESTRICT, 
	FOREIGN KEY(prize_table_revision_id) REFERENCES zucai_prize_table_revisions (prize_table_revision_id) ON DELETE RESTRICT, 
	FOREIGN KEY(fixed_prize_policy_revision_id) REFERENCES zucai_fixed_prize_policy_revisions (fixed_prize_policy_revision_id) ON DELETE RESTRICT, 
	FOREIGN KEY(action_id) REFERENCES actions (action_id) ON DELETE RESTRICT
);

-- table operator_worker_jobs
CREATE TABLE operator_worker_jobs (
	worker_job_id TEXT NOT NULL, 
	job_kind TEXT NOT NULL, 
	source_object_type TEXT NOT NULL, 
	source_object_id TEXT NOT NULL, 
	state TEXT NOT NULL, 
	lease_owner TEXT, 
	lease_expires_at TEXT, 
	attempt_count INTEGER DEFAULT '0' NOT NULL, 
	available_at TEXT NOT NULL, 
	last_error_code TEXT, 
	result_action_id TEXT, 
	result_object_type TEXT, 
	result_object_id TEXT, 
	created_at TEXT NOT NULL, 
	updated_at TEXT NOT NULL, 
	PRIMARY KEY (worker_job_id), 
	CONSTRAINT ck_operator_worker_job_kind CHECK (job_kind IN ('evidence_freeze', 'market_baseline', 'candidate_generation', 'task_settlement', 'review_materialization', 'scoreboard_review_completion')), 
	CONSTRAINT ck_operator_worker_job_state CHECK (state IN ('queued', 'leased', 'completed', 'failed')), 
	CONSTRAINT ck_operator_worker_job_attempts CHECK (attempt_count >= 0), 
	CONSTRAINT ck_operator_worker_job_lease_state CHECK ((state = 'leased' AND lease_owner IS NOT NULL AND lease_expires_at IS NOT NULL) OR (state != 'leased' AND lease_owner IS NULL AND lease_expires_at IS NULL)), 
	CONSTRAINT ck_operator_worker_job_result_ref CHECK ((state = 'completed' AND result_action_id IS NOT NULL AND result_object_type IS NOT NULL AND result_object_id IS NOT NULL) OR (state != 'completed' AND result_action_id IS NULL AND result_object_type IS NULL AND result_object_id IS NULL)), 
	CONSTRAINT uq_operator_worker_job_source UNIQUE (job_kind, source_object_type, source_object_id), 
	FOREIGN KEY(result_action_id) REFERENCES actions (action_id) ON DELETE RESTRICT
);

