-- table zucai_fixed_prize_policy_revisions
CREATE TABLE zucai_fixed_prize_policy_revisions (
	fixed_prize_policy_revision_id TEXT NOT NULL, 
	fixed_prize_policy_family_id TEXT NOT NULL, 
	revision_no INTEGER NOT NULL, 
	supersedes_revision_id TEXT, 
	policy_version TEXT NOT NULL, 
	ticket_kind TEXT NOT NULL, 
	currency TEXT NOT NULL, 
	standard_unit_stake_minor INTEGER NOT NULL, 
	official_void_rule TEXT NOT NULL, 
	effective_at TEXT NOT NULL, 
	content_hash TEXT NOT NULL, 
	action_id TEXT NOT NULL, 
	created_at TEXT NOT NULL, 
	PRIMARY KEY (fixed_prize_policy_revision_id), 
	CONSTRAINT ck_zucai_fixed_policy_revision CHECK (revision_no >= 1), 
	CONSTRAINT ck_zucai_fixed_policy_kind CHECK (ticket_kind IN ('sfc', 'renjiu')), 
	CONSTRAINT ck_zucai_fixed_policy_currency CHECK (length(currency) = 3), 
	CONSTRAINT ck_zucai_fixed_policy_unit_stake CHECK (standard_unit_stake_minor > 0), 
	CONSTRAINT ck_zucai_fixed_policy_void_rule CHECK (official_void_rule = 'all_faces_match'), 
	CONSTRAINT uq_zucai_fixed_policy_revision UNIQUE (fixed_prize_policy_family_id, revision_no), 
	UNIQUE (supersedes_revision_id), 
	FOREIGN KEY(supersedes_revision_id) REFERENCES zucai_fixed_prize_policy_revisions (fixed_prize_policy_revision_id) ON DELETE RESTRICT, 
	UNIQUE (action_id), 
	FOREIGN KEY(action_id) REFERENCES actions (action_id) ON DELETE RESTRICT
);

-- table zucai_fixed_prize_policy_tiers
CREATE TABLE zucai_fixed_prize_policy_tiers (
	fixed_prize_policy_tier_id TEXT NOT NULL, 
	fixed_prize_policy_revision_id TEXT NOT NULL, 
	tier_index INTEGER NOT NULL, 
	tier_code TEXT NOT NULL, 
	required_correct_count INTEGER NOT NULL, 
	PRIMARY KEY (fixed_prize_policy_tier_id), 
	CONSTRAINT ck_zucai_fixed_policy_tier_index CHECK (tier_index >= 0), 
	CONSTRAINT ck_zucai_fixed_policy_tier_correct CHECK (required_correct_count BETWEEN 1 AND 14), 
	CONSTRAINT uq_zucai_fixed_policy_tier_index UNIQUE (fixed_prize_policy_revision_id, tier_index), 
	CONSTRAINT uq_zucai_fixed_policy_tier_code UNIQUE (fixed_prize_policy_revision_id, tier_code), 
	CONSTRAINT uq_zucai_fixed_policy_tier_correct UNIQUE (fixed_prize_policy_revision_id, required_correct_count), 
	FOREIGN KEY(fixed_prize_policy_revision_id) REFERENCES zucai_fixed_prize_policy_revisions (fixed_prize_policy_revision_id) ON DELETE RESTRICT
);

-- table zucai_prize_table_revisions
CREATE TABLE zucai_prize_table_revisions (
	prize_table_revision_id TEXT NOT NULL, 
	prize_table_family_id TEXT NOT NULL, 
	revision_no INTEGER NOT NULL, 
	supersedes_revision_id TEXT, 
	issue TEXT NOT NULL, 
	currency TEXT NOT NULL, 
	published_at TEXT NOT NULL, 
	source_artifact_retrieval_id TEXT NOT NULL, 
	tier_count INTEGER NOT NULL, 
	content_hash TEXT NOT NULL, 
	action_id TEXT NOT NULL, 
	created_at TEXT NOT NULL, 
	PRIMARY KEY (prize_table_revision_id), 
	CONSTRAINT ck_zucai_prize_revision CHECK (revision_no >= 1), 
	CONSTRAINT ck_zucai_prize_currency CHECK (currency = 'CNY'), 
	CONSTRAINT ck_zucai_prize_tier_count CHECK (tier_count = 3), 
	CONSTRAINT uq_zucai_prize_family_revision UNIQUE (prize_table_family_id, revision_no), 
	UNIQUE (supersedes_revision_id), 
	FOREIGN KEY(supersedes_revision_id) REFERENCES zucai_prize_table_revisions (prize_table_revision_id) ON DELETE RESTRICT, 
	FOREIGN KEY(source_artifact_retrieval_id) REFERENCES artifact_retrievals (artifact_retrieval_id) ON DELETE RESTRICT, 
	FOREIGN KEY(action_id) REFERENCES actions (action_id) ON DELETE RESTRICT
);

-- table zucai_prize_table_tiers
CREATE TABLE zucai_prize_table_tiers (
	prize_table_tier_id TEXT NOT NULL, 
	prize_table_revision_id TEXT NOT NULL, 
	tier_index INTEGER NOT NULL, 
	tier_code TEXT NOT NULL, 
	ticket_kind TEXT NOT NULL, 
	required_correct_count INTEGER NOT NULL, 
	official_winning_note_count INTEGER NOT NULL, 
	payout_minor_per_winning_note INTEGER NOT NULL, 
	PRIMARY KEY (prize_table_tier_id), 
	CONSTRAINT ck_zucai_prize_tier_index CHECK (tier_index BETWEEN 0 AND 2), 
	CONSTRAINT ck_zucai_prize_tier_identity CHECK ((tier_code = 'sfc_first' AND ticket_kind = 'sfc' AND required_correct_count = 14) OR (tier_code = 'sfc_second' AND ticket_kind = 'sfc' AND required_correct_count = 13) OR (tier_code = 'renjiu_first' AND ticket_kind = 'renjiu' AND required_correct_count = 9)), 
	CONSTRAINT ck_zucai_prize_winning_count CHECK (official_winning_note_count >= 0), 
	CONSTRAINT ck_zucai_prize_payout CHECK (payout_minor_per_winning_note >= 0), 
	CONSTRAINT uq_zucai_prize_tier_index UNIQUE (prize_table_revision_id, tier_index), 
	CONSTRAINT uq_zucai_prize_tier_code UNIQUE (prize_table_revision_id, tier_code), 
	FOREIGN KEY(prize_table_revision_id) REFERENCES zucai_prize_table_revisions (prize_table_revision_id) ON DELETE RESTRICT
);

-- trigger actions_historical_replay_pair_insert
CREATE TRIGGER actions_historical_replay_pair_insert
            BEFORE INSERT ON actions
            WHEN NOT (
              (NEW.historical_replay = 0 AND NEW.replay_run_id IS NULL) OR
              (NEW.historical_replay = 1 AND NEW.replay_run_id IS NOT NULL)
            )
            BEGIN
              SELECT RAISE(ABORT, 'historical replay provenance pair is invalid');
            END;

-- trigger actions_historical_replay_pair_update
CREATE TRIGGER actions_historical_replay_pair_update
            BEFORE UPDATE ON actions
            WHEN NOT (
              (NEW.historical_replay = 0 AND NEW.replay_run_id IS NULL) OR
              (NEW.historical_replay = 1 AND NEW.replay_run_id IS NOT NULL)
            )
            BEGIN
              SELECT RAISE(ABORT, 'historical replay provenance pair is invalid');
            END;

-- trigger actions_replay_run_reference_insert
CREATE TRIGGER actions_replay_run_reference_insert
            BEFORE INSERT ON actions
            WHEN NEW.replay_run_id IS NOT NULL AND NOT EXISTS (
              SELECT 1 FROM historical_replay_runs
              WHERE replay_run_id = NEW.replay_run_id
            )
            BEGIN
              SELECT RAISE(ABORT, 'historical replay run does not exist');
            END;

-- trigger actions_replay_run_reference_update
CREATE TRIGGER actions_replay_run_reference_update
            BEFORE UPDATE ON actions
            WHEN NEW.replay_run_id IS NOT NULL AND NOT EXISTS (
              SELECT 1 FROM historical_replay_runs
              WHERE replay_run_id = NEW.replay_run_id
            )
            BEGIN
              SELECT RAISE(ABORT, 'historical replay run does not exist');
            END;

-- trigger baseline_envelope_linear_child
CREATE TRIGGER baseline_envelope_linear_child
            BEFORE INSERT ON operator_baseline_envelope_revisions
            WHEN NEW.supersedes_revision_id IS NOT NULL
            BEGIN
              SELECT CASE WHEN NOT EXISTS (
                SELECT 1
                FROM operator_baseline_envelope_revisions AS parent
                WHERE parent.baseline_envelope_revision_id = NEW.supersedes_revision_id
                  AND parent.baseline_envelope_family_id = NEW.baseline_envelope_family_id
              ) THEN RAISE(ABORT, 'superseding revision must belong to same family') END;
              SELECT CASE WHEN NEW.revision_no != (
                SELECT parent.revision_no + 1
                FROM operator_baseline_envelope_revisions AS parent
                WHERE parent.baseline_envelope_revision_id = NEW.supersedes_revision_id
              ) THEN RAISE(ABORT, 'revision_no must immediately follow parent') END;
            END;

-- trigger baseline_envelope_no_delete
CREATE TRIGGER baseline_envelope_no_delete
                BEFORE DELETE ON operator_baseline_envelope_revisions
                BEGIN
                  SELECT RAISE(ABORT, 'operator_baseline_envelope_revisions is append-only');
                END;

-- trigger baseline_envelope_no_update
CREATE TRIGGER baseline_envelope_no_update
                BEFORE UPDATE ON operator_baseline_envelope_revisions
                BEGIN
                  SELECT RAISE(ABORT, 'operator_baseline_envelope_revisions is append-only');
                END;

-- trigger baseline_envelope_root_revision_no
CREATE TRIGGER baseline_envelope_root_revision_no
            BEFORE INSERT ON operator_baseline_envelope_revisions
            WHEN NEW.supersedes_revision_id IS NULL AND NEW.revision_no != 1
            BEGIN
              SELECT RAISE(ABORT, 'root revision_no must be 1');
            END;

-- trigger baseline_envelope_single_root
CREATE TRIGGER baseline_envelope_single_root
            BEFORE INSERT ON operator_baseline_envelope_revisions
            WHEN NEW.supersedes_revision_id IS NULL
              AND EXISTS (
                SELECT 1
                FROM operator_baseline_envelope_revisions
                WHERE baseline_envelope_family_id = NEW.baseline_envelope_family_id
                  AND supersedes_revision_id IS NULL
              )
            BEGIN
              SELECT RAISE(ABORT, 'baseline_envelope_family_id already has a root revision');
            END;

-- trigger baseline_envelope_typed_action
CREATE TRIGGER baseline_envelope_typed_action
            BEFORE INSERT ON operator_baseline_envelope_revisions
            WHEN NOT EXISTS (
              SELECT 1 FROM actions
              WHERE action_id = NEW.action_id
                AND action_type = 'record_baseline_envelope'
                AND 
      (
        actor_role = 'judge_operator' OR
        (
          actor_role = 'replay_adjudicator' AND
          historical_replay = 1 AND
          replay_run_id IS NOT NULL
        )
      )
    
                AND status IN ('accepted', 'committed')
            )
            BEGIN
              SELECT RAISE(ABORT, 'operator_baseline_envelope_revisions requires its typed Action');
            END;

-- trigger candidate_generation_request_typed_action
CREATE TRIGGER candidate_generation_request_typed_action
            BEFORE INSERT ON operator_candidate_generation_requests
            WHEN NOT EXISTS (
              SELECT 1 FROM actions
              WHERE action_id = NEW.action_id
                AND action_type IN ('request_candidate_generation', 'record_ticket_audit_override')
                AND 
      (
        actor_role = 'judge_operator' OR
        (
          actor_role = 'replay_adjudicator' AND
          historical_replay = 1 AND
          replay_run_id IS NOT NULL
        )
      )
    
                AND status IN ('accepted', 'committed')
            )
            BEGIN
              SELECT RAISE(ABORT, 'operator_candidate_generation_requests requires its typed Action');
            END;

-- trigger candidate_selection_linear_revision
CREATE TRIGGER candidate_selection_linear_revision
            BEFORE INSERT ON operator_candidate_selections
            WHEN (NEW.supersedes_revision_id IS NULL AND NEW.revision_no != 1)
              OR (NEW.supersedes_revision_id IS NOT NULL AND NOT EXISTS (
                SELECT 1 FROM operator_candidate_selections AS parent
                WHERE parent.candidate_selection_id = NEW.supersedes_revision_id
                  AND parent.candidate_selection_family_id = NEW.candidate_selection_family_id
                  AND NEW.revision_no = parent.revision_no + 1
              ))
            BEGIN
              SELECT RAISE(ABORT, 'revision must directly follow its family predecessor');
            END;

-- trigger candidate_selection_single_root
CREATE TRIGGER candidate_selection_single_root
            BEFORE INSERT ON operator_candidate_selections
            WHEN NEW.supersedes_revision_id IS NULL
              AND EXISTS (
                SELECT 1 FROM operator_candidate_selections
                WHERE candidate_selection_family_id = NEW.candidate_selection_family_id
                  AND supersedes_revision_id IS NULL
              )
            BEGIN
              SELECT RAISE(ABORT, 'candidate_selection_family_id already has a root revision');
            END;

-- trigger candidate_selection_typed_action
CREATE TRIGGER candidate_selection_typed_action
            BEFORE INSERT ON operator_candidate_selections
            WHEN NOT EXISTS (
              SELECT 1 FROM actions
              WHERE action_id = NEW.action_id
                AND action_type = 'select_ticket_candidate'
                AND actor_role = 'judge_operator'
                AND status IN ('accepted', 'committed')
            )
            BEGIN
              SELECT RAISE(ABORT, 'operator_candidate_selections requires its typed Action');
            END;

-- trigger cash_transactions_v2_money_insert
CREATE TRIGGER cash_transactions_v2_money_insert
        BEFORE INSERT ON cash_transactions
        WHEN (NEW.amount_minor IS NOT NULL OR NEW.currency IS NOT NULL)
          AND NOT (
            NEW.amount_minor IS NOT NULL
            AND NEW.amount_minor != 0
            AND NEW.currency IS NOT NULL
            AND length(NEW.currency) = 3
            AND CAST(ROUND(NEW.amount * 100) AS INTEGER) = NEW.amount_minor
            AND EXISTS (
              SELECT 1 FROM cash_accounts AS account
              WHERE account.account_id = NEW.account_id
                AND account.currency = NEW.currency
            )
          )
        BEGIN
          SELECT RAISE(ABORT, 'v2 cash minor-unit fields do not reconcile');
        END;

