        END;

-- trigger judgment_prescription_linear_child
CREATE TRIGGER judgment_prescription_linear_child
            BEFORE INSERT ON operator_judgment_prescription_revisions
            WHEN NEW.supersedes_revision_id IS NOT NULL
            BEGIN
              SELECT CASE WHEN NOT EXISTS (
                SELECT 1
                FROM operator_judgment_prescription_revisions AS parent
                WHERE parent.judgment_prescription_revision_id = NEW.supersedes_revision_id
                  AND parent.judgment_prescription_family_id = NEW.judgment_prescription_family_id
              ) THEN RAISE(ABORT, 'superseding revision must belong to same family') END;
              SELECT CASE WHEN NEW.revision_no != (
                SELECT parent.revision_no + 1
                FROM operator_judgment_prescription_revisions AS parent
                WHERE parent.judgment_prescription_revision_id = NEW.supersedes_revision_id
              ) THEN RAISE(ABORT, 'revision_no must immediately follow parent') END;
            END;

