-- trigger operator_match_judgment_linear_child
CREATE TRIGGER operator_match_judgment_linear_child
            BEFORE INSERT ON operator_match_judgment_revisions
            WHEN NEW.supersedes_revision_id IS NOT NULL
            BEGIN
              SELECT CASE WHEN NOT EXISTS (
                SELECT 1
                FROM operator_match_judgment_revisions AS parent
                WHERE parent.operator_match_judgment_revision_id = NEW.supersedes_revision_id
                  AND parent.operator_match_judgment_family_id = NEW.operator_match_judgment_family_id
              ) THEN RAISE(ABORT, 'superseding revision must belong to same family') END;
              SELECT CASE WHEN NEW.revision_no != (
                SELECT parent.revision_no + 1
                FROM operator_match_judgment_revisions AS parent
                WHERE parent.operator_match_judgment_revision_id = NEW.supersedes_revision_id
              ) THEN RAISE(ABORT, 'revision_no must immediately follow parent') END;
            END;

