-- trigger operator_result_set_linear_child
CREATE TRIGGER operator_result_set_linear_child
            BEFORE INSERT ON operator_result_set_revisions
            WHEN NEW.supersedes_revision_id IS NOT NULL
            BEGIN
              SELECT CASE WHEN NOT EXISTS (
                SELECT 1 FROM operator_result_set_revisions AS parent
                WHERE parent.result_set_revision_id = NEW.supersedes_revision_id
                  AND parent.result_set_family_id = NEW.result_set_family_id AND lane = NEW.lane AND business_key = NEW.business_key AND task_family_id = NEW.task_family_id
                  AND NEW.revision_no = parent.revision_no + 1
              ) THEN RAISE(ABORT, 'revision must directly follow its current family leaf') END;
              SELECT CASE WHEN EXISTS (
                SELECT 1 FROM operator_result_set_revisions AS child
                WHERE child.supersedes_revision_id = NEW.supersedes_revision_id
              ) THEN RAISE(ABORT, 'revision predecessor already has a child') END;
            END;

