        BEFORE INSERT ON official_sale_slate_revisions
        WHEN NEW.supersedes_slate_revision_id IS NULL AND NEW.revision_no != 1
        BEGIN
          SELECT RAISE(ABORT, 'root revision_no must be 1');
        END;

