-- trigger operator_ticket_decision_lineage_linear_revision
CREATE TRIGGER operator_ticket_decision_lineage_linear_revision
            BEFORE INSERT ON operator_ticket_decision_lineage_revisions
            WHEN (NEW.supersedes_revision_id IS NULL AND NEW.revision_no != 1)
              OR (NEW.supersedes_revision_id IS NOT NULL AND NOT EXISTS (
                SELECT 1 FROM operator_ticket_decision_lineage_revisions AS parent
                WHERE parent.lineage_revision_id = NEW.supersedes_revision_id
                  AND parent.lineage_family_id = NEW.lineage_family_id
                  AND NEW.revision_no = parent.revision_no + 1
              ))
            BEGIN
              SELECT RAISE(ABORT, 'revision must directly follow its family predecessor');
            END;

