-- trigger operator_ticket_note_parent_consistency
CREATE TRIGGER operator_ticket_note_parent_consistency
        BEFORE INSERT ON operator_ticket_notes
        WHEN NOT EXISTS (
          SELECT 1
          FROM tickets AS ticket
          WHERE ticket.ticket_id = NEW.ticket_id
