            AND ticket.currency = NEW.currency
            AND ticket.fixed_prize_policy_revision_id
                IS NEW.fixed_prize_policy_revision_id
        )
        BEGIN
          SELECT RAISE(ABORT, 'ticket note policy or currency does not match ticket');
        END;

