-- trigger operator_ticket_settlement_linear_child
CREATE TRIGGER operator_ticket_settlement_linear_child
            BEFORE INSERT ON operator_ticket_settlement_revisions
            WHEN NEW.supersedes_revision_id IS NOT NULL
            BEGIN
              SELECT CASE WHEN NOT EXISTS (
                SELECT 1 FROM operator_ticket_settlement_revisions AS parent
                WHERE parent.settlement_revision_id = NEW.supersedes_revision_id
                  AND parent.settlement_family_id = NEW.settlement_family_id AND ticket_id = NEW.ticket_id
                  AND NEW.revision_no = parent.revision_no + 1
              ) THEN RAISE(ABORT, 'revision must directly follow its current family leaf') END;
              SELECT CASE WHEN EXISTS (
                SELECT 1 FROM operator_ticket_settlement_revisions AS child
                WHERE child.supersedes_revision_id = NEW.supersedes_revision_id
              ) THEN RAISE(ABORT, 'revision predecessor already has a child') END;
            END;

