-- trigger zucai_fixed_prize_policy_tiers_no_delete
CREATE TRIGGER zucai_fixed_prize_policy_tiers_no_delete
                BEFORE DELETE ON zucai_fixed_prize_policy_tiers
                BEGIN
                  SELECT RAISE(ABORT, 'zucai_fixed_prize_policy_tiers is append-only');
                END;

-- trigger zucai_fixed_prize_policy_tiers_no_late_insert
CREATE TRIGGER zucai_fixed_prize_policy_tiers_no_late_insert
            BEFORE INSERT ON zucai_fixed_prize_policy_tiers
            WHEN EXISTS (
              SELECT 1
              FROM actions AS action
              JOIN zucai_fixed_prize_policy_revisions AS revision ON revision.fixed_prize_policy_revision_id = NEW.fixed_prize_policy_revision_id
              WHERE action.action_id = revision.action_id
                AND action.status = 'committed'
            )
            BEGIN
              SELECT RAISE(ABORT, 'zucai_fixed_prize_policy_tiers is append-only after commit');
            END;

-- trigger zucai_fixed_prize_policy_tiers_no_update
CREATE TRIGGER zucai_fixed_prize_policy_tiers_no_update
                BEFORE UPDATE ON zucai_fixed_prize_policy_tiers
                BEGIN
                  SELECT RAISE(ABORT, 'zucai_fixed_prize_policy_tiers is append-only');
                END;

-- trigger zucai_fixed_prize_policy_typed_action
CREATE TRIGGER zucai_fixed_prize_policy_typed_action
            BEFORE INSERT ON zucai_fixed_prize_policy_revisions
            WHEN NOT EXISTS (
              SELECT 1 FROM actions
              WHERE action_id = NEW.action_id
                AND action_type = 'register_zucai_fixed_prize_policy'
                AND actor_role = 'deterministic_system'
                AND status IN ('accepted', 'committed')
            )
            BEGIN
              SELECT RAISE(ABORT, 'zucai_fixed_prize_policy_revisions requires its typed Action');
            END;

-- trigger zucai_prize_table_complete_before_commit
CREATE TRIGGER zucai_prize_table_complete_before_commit
        BEFORE UPDATE OF status ON actions
        WHEN NEW.status = 'committed'
          AND NEW.action_type = 'import_result_evidence_set'
          AND EXISTS (
            SELECT 1
            FROM zucai_prize_table_revisions AS prize
            WHERE prize.action_id = NEW.action_id
              AND prize.tier_count != (
                SELECT COUNT(*) FROM zucai_prize_table_tiers AS tier
                WHERE tier.prize_table_revision_id = prize.prize_table_revision_id
              )
          )
        BEGIN
          SELECT RAISE(ABORT, 'prize-table tier counts do not reconcile');
        END;

-- trigger zucai_prize_table_linear_child
CREATE TRIGGER zucai_prize_table_linear_child
            BEFORE INSERT ON zucai_prize_table_revisions
            WHEN NEW.supersedes_revision_id IS NOT NULL
            BEGIN
              SELECT CASE WHEN NOT EXISTS (
                SELECT 1 FROM zucai_prize_table_revisions AS parent
                WHERE parent.prize_table_revision_id = NEW.supersedes_revision_id
                  AND parent.prize_table_family_id = NEW.prize_table_family_id AND issue = NEW.issue AND currency = NEW.currency
                  AND NEW.revision_no = parent.revision_no + 1
              ) THEN RAISE(ABORT, 'revision must directly follow its current family leaf') END;
              SELECT CASE WHEN EXISTS (
                SELECT 1 FROM zucai_prize_table_revisions AS child
                WHERE child.supersedes_revision_id = NEW.supersedes_revision_id
              ) THEN RAISE(ABORT, 'revision predecessor already has a child') END;
            END;

-- trigger zucai_prize_table_revisions_no_delete
CREATE TRIGGER zucai_prize_table_revisions_no_delete
                BEFORE DELETE ON zucai_prize_table_revisions
                BEGIN
                  SELECT RAISE(ABORT, 'zucai_prize_table_revisions is append-only');
                END;

-- trigger zucai_prize_table_revisions_no_update
CREATE TRIGGER zucai_prize_table_revisions_no_update
                BEFORE UPDATE ON zucai_prize_table_revisions
                BEGIN
                  SELECT RAISE(ABORT, 'zucai_prize_table_revisions is append-only');
                END;

-- trigger zucai_prize_table_root_revision_no
CREATE TRIGGER zucai_prize_table_root_revision_no
            BEFORE INSERT ON zucai_prize_table_revisions
            WHEN NEW.supersedes_revision_id IS NULL AND NEW.revision_no != 1
            BEGIN
              SELECT RAISE(ABORT, 'root revision_no must be 1');
            END;

-- trigger zucai_prize_table_single_root
CREATE TRIGGER zucai_prize_table_single_root
            BEFORE INSERT ON zucai_prize_table_revisions
            WHEN NEW.supersedes_revision_id IS NULL
              AND EXISTS (
                SELECT 1 FROM zucai_prize_table_revisions
                WHERE prize_table_family_id = NEW.prize_table_family_id
                  AND supersedes_revision_id IS NULL
              )
            BEGIN
              SELECT RAISE(ABORT, 'prize_table_family_id already has a root revision');
            END;

-- trigger zucai_prize_table_tiers_no_delete
CREATE TRIGGER zucai_prize_table_tiers_no_delete
                BEFORE DELETE ON zucai_prize_table_tiers
                BEGIN
                  SELECT RAISE(ABORT, 'zucai_prize_table_tiers is append-only');
                END;

-- trigger zucai_prize_table_tiers_no_update
CREATE TRIGGER zucai_prize_table_tiers_no_update
                BEFORE UPDATE ON zucai_prize_table_tiers
                BEGIN
                  SELECT RAISE(ABORT, 'zucai_prize_table_tiers is append-only');
                END;

-- trigger zucai_prize_table_typed_action
CREATE TRIGGER zucai_prize_table_typed_action
        BEFORE INSERT ON zucai_prize_table_revisions
        WHEN NOT EXISTS (
          SELECT 1 FROM actions
          WHERE action_id = NEW.action_id
            AND action_type = 'import_result_evidence_set'
            AND actor_role = 'deterministic_system'
            AND status IN ('accepted', 'committed')
        )
        BEGIN
          SELECT RAISE(ABORT, 'prize table requires its deterministic import Action');
        END;

